/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"#1":{"묶음":[{"머리":"국제물류의 개념과 기능","줄":[{"t":"국제물류: 조달·생산·판매 등 물류활동이 국경을 넘어 이루어지는 물류. 국내물류보다 제도적·환경적 제약을 많이 받는다.","src":"기출 2024-1"},{"t":"국제물류는 해외고객 서비스 향상, 국가 경제발전과 물가안정, 제품·기업의 국제경쟁력에 기여한다.","src":"기출 2021-1"},{"t":"물류의 사회적 기능: 생산자와 소비자의 수급 불일치 해소, 생산시점과 소비시점의 불일치(시간적 격차) 조정, 생산지와 소비지의 장소적·거리적 격차 단축, 생산물품과 소비물품의 품질 동일 유지.","src":"기출 2023-1"},{"t":"물류는 정보의 비대칭성을 줄이는 방향으로 기능한다(강화가 아님).","src":"기출 2023-1"},{"t":"국제 물동량은 지속적으로 증가하고 있다.","src":"기출 2021-1"},{"t":"9.11테러 이후 국경 간 물자 이동에서 물류보안제도의 중요성이 높아졌다.","src":"기출 2024-1"}]},{"머리":"국제물류와 국내물류의 비교","줄":[{"t":"리드타임: 국제물류가 길다(운송거리·수출입절차·통관절차 영향). 리드타임이 길면 재고량(안전재고)이 늘어난다.","src":"기출 2021-1 | 기출 2024-1"},{"t":"운송방법: 국제물류는 주로 복합운송, 국내물류는 주로 공로운송.","src":"기출 2023-21"},{"t":"재고수준: 국제물류는 주문시간이 길고 불확실성이 커서 재고 수준이 높다.","src":"기출 2023-21"},{"t":"화물위험: 국제물류는 장기운송과 환적 등으로 위험이 높다. 국내물류는 단기운송이라 위험이 낮다.","src":"기출 2023-21"},{"t":"서류작업: 국제물류는 각종 무역·운송서류가 필요해 복잡하다. 국내물류는 구매주문서와 송장 정도로 간단하다.","src":"기출 2023-21 | 기출 2026-2"},{"t":"재무적 위험: 국제물류는 환리스크로 높다. 국내물류는 환리스크가 없어 낮다.","src":"기출 2023-21"},{"t":"국제물류는 관리의 복잡성, 리드타임·불확실성, 환율변동 위험, 국가별 유통채널·상관습 차이를 갖는다. 거래비용이 감소하는 것은 아니다.","src":"기출 2024-4 | 기출 2026-2"},{"t":"국제물류는 통관절차를 수반한다. 서류·거래절차가 단순하고 표준화된 것이 아니다.","src":"기출 2025-2 | 기출 2026-2"},{"t":"국제물류에는 선화증권·항공화물운송장·상업송장·수출신고서 등 다양한 서류, 화물운송주선인·통관업자 등 여러 중개인이 있고 주문절차와 주문처리가 복잡하다. 운송관리가 용이하지 않다.","src":"기출 2025-2"},{"t":"국제물류는 운송수단 간 통합과 조정이 중요하다.","src":"기출 2026-2"}]},{"머리":"국제물류 환경 변화(추세)","줄":[{"t":"선박 대형화로 항만 수심이 깊어지고 Post Panamax Crane가 도입되었다. 항공기도 대형화 추세이다.","src":"기출 2021-2"},{"t":"글로벌 공급사슬 관점의 국제물류관리, 물류체계의 플랫폼화·고도화가 중요해지고 있다.","src":"기출 2021-2"},{"t":"물류기능은 개별 수행이 아니라 통합 수행하는 추세. 제3자물류(3PL)·4PL 시장 진입과 역할이 확대되고 있다.","src":"기출 2021-4 | 기출 2023-2 | 기출 2026-1"},{"t":"초대형 컨테이너선 증가로 허브항만 경쟁이 심해지고 있다.","src":"기출 2021-4"},{"t":"허브항만은 지역경제 협력 거점으로 다각화, 전자상거래로 온라인 정보망과 오프라인 물류망의 동조화가 강화되고 있다.","src":"기출 2023-2"},{"t":"환경물류(소비 이후 재사용·폐기까지 환경유해요소 최소화), 녹색물류, 회수물류에 대한 관심이 높아지고 있다.","src":"기출 2023-2 | 기출 2025-1 | 기출 2026-1"},{"t":"물류기업 간 수평적·수직적 통합, 전략적 제휴, 인수합병이 증가하고 있다. 시장진입 규제는 강화가 아니라 완화 추세이다.","src":"기출 2023-19 | 기출 2025-1"},{"t":"온실가스 감축을 위해 메탄올 연료 선박 건조가 증가하고 있다.","src":"기출 2023-19"},{"t":"4차 산업혁명 디지털 기술(블록체인 등)을 활용한 운영효율·고객만족 제고가 늘고 있다.","src":"기출 2023-19 | 기출 2022-10"},{"t":"코로나 팬데믹으로 전자상거래 비중이 증가했다. 전자상거래로 물류시스템의 가시성 확보가 요구된다.","src":"기출 2023-19 | 기출 2026-1"},{"t":"글로벌 불확실성 증가로 네트워크 탄력성과 유연한 공급망 관리가 요구된다. 물류 수요는 물류기업 주도에서 소비자 주도로 전환되었다.","src":"기출 2026-1"},{"t":"물류 위험관리와 물류보안이 강화되고 있다.","src":"기출 2025-1"},{"t":"국제물류기업은 공용터미널에 의존하기보다 전용터미널을 확보해 체선·체화를 줄이려 한다.","src":"보충 | 기출 2023-2"}]},{"머리":"글로벌 소싱·운송수단 선택","줄":[{"t":"글로벌 소싱의 이유: 비용절감, 상품개발과 생산기간 단축, 핵심역량 집중, 조직효율성 개선. 인력증대는 해당하지 않는다.","src":"기출 2021-5"},{"t":"운송수단 선정: 운송비뿐 아니라 재고비용·보관비용·리드타임·화물특성을 고려해 총비용 최소화.","src":"기출 2024-2"},{"t":"항공운송은 해상운송에 비해 재고비용·보관비용을 줄일 수 있다.","src":"기출 2024-2"},{"t":"해상운송은 대량운송으로 단위당 운송비를 줄인다. 소량화물은 혼재운송·공동 수배송으로 적재효율을 높인다.","src":"기출 2024-2"},{"t":"컨테이너 단위화물은 개품화물(break bulk cargo)에 비해 하역기간이 단축된다.","src":"기출 2024-2"},{"t":"해상운송의 특징: 대량화물 장거리 수송, 저렴한 운송비, 자유로운 운송로(수송로), 전천후. 문전수송(Door-to-Door)과 빠른 속도는 해상운송의 장점이 아니다.","src":"기출 2025-20 | 기출 2026-4"}]}],"함정":[{"x":"국제물류는 국내물류에 비해 짧은 리드타임을 가지고 있다.","o":"국제물류는 국내물류에 비해 긴 리드타임을 가진다.","src":"기출 2021-1"},{"x":"국제특송업체들은 항공화물운송 효율화를 위해 항공기 소형화를 추진하고 있다.","o":"국제특송업체들은 항공화물운송 효율화를 위해 항공기 대형화를 추진한다.","src":"기출 2021-2"},{"x":"정보의 비대칭성을 강화하여 생산자의 경쟁력을 제고하는 기능을 한다.","o":"출제 오답(물류는 정보의 비대칭성을 줄이는 방향으로 기능한다)","src":"기출 2023-1"},{"x":"국제물류기업은 항만이나 공항의 공용터미널을 지속적으로 활용하여 체선ㆍ체화를 감소시키고 있다.","o":"국제물류기업은 공용터미널에 의존하기보다 전용터미널을 확보·운영해 체선·체화를 줄이려는 추세이다(보충).","src":"기출 2023-2"},{"x":"코로나 팬데믹의 영향으로 전자상거래 비중이 감소하는 추세이다.","o":"코로나 팬데믹의 영향으로 전자상거래 비중이 증가하는 추세이다.","src":"기출 2023-19"},{"x":"국제물류활동에 따른 리드타임의 증가는 재고량 감소에 영향을 미친다.","o":"국제물류의 리드타임 증가는 안전재고 확대로 재고량 증가에 영향을 미친다.","src":"기출 2024-1"},{"x":"컨테이너를 이용한 단위화물은 개품화물(break bulk cargo)에 비해 하역기간이 늘어날 수 있다.","o":"컨테이너를 이용한 단위화물은 개품화물에 비해 하역기간이 단축된다.","src":"기출 2024-2"},{"x":"해상 또는 항공운송으로 이루어지므로 운송관리가 비교적 용이하다.","o":"국제물류는 해상·항공 운송과 통관, 다수 중개인이 얽혀 운송관리가 복잡하다.","src":"기출 2025-2"},{"x":"물류의 수요는 소비자 주도에서 물류기업 주도로 전환되어 최적화된 서비스를 공급하고 있다.","o":"물류의 수요는 물류기업 주도에서 소비자 주도로 전환되었다.","src":"기출 2026-1"},{"x":"국제물류는 국내물류에 비해 서류 및 거래절차가 단순하고 표준화되어 있다.","o":"국제물류는 국내물류에 비해 서류와 거래절차가 복잡하다.","src":"기출 2026-2"}]},"#2":{"묶음":[{"머리":"국제물류서비스의 단계별 발전","줄":[{"t":"순서: 수출입 물류체계 → 현지국(현지) 물류체계 → 거점 물류체계 → 글로벌 공급망(SCM) 네트워크 체계.","src":"기출 2025-4"},{"t":"수출입 물류체계: 수출입을 중심으로 이루어지는 일련의 물류활동을 관리하는 단계.","src":"기출 2025-4"},{"t":"현지국 물류체계: 국가별 현지 자회사를 중심으로 물류·생산활동을 수행하고 현지국에 생산거점을 둔다. 본국 중심 생산이 아니다.","src":"기출 2022-1 | 기출 2025-4"},{"t":"거점 물류체계: 기업 활동의 전부 또는 일부를 특정 경제권의 투자가치가 높은 지역에 배치하고 그 지역거점 중심으로 지역 경제권 전체를 담당한다.","src":"기출 2022-1 | 기출 2025-4"},{"t":"글로벌 SCM 네트워크 체계: 조달·생산·판매·유통 등 전 기업 활동이 전 세계를 대상으로 진행. 정보자원·물류인프라·비즈니스 프로세스를 국경을 넘어 통합 관리·조정한다.","src":"기출 2022-1 | 기출 2025-4"}]},{"머리":"국제물류시스템 유형 4가지","줄":[{"t":"고전적 시스템(Classical system): 수출국 공장에서 해외 자회사 창고로 저속·대량운송수단을 써서 운임을 절감한다. 자회사 창고는 보관 중심, 재고를 자회사 창고에 둔다.","src":"기출 2022-2 | 보충"},{"t":"직송 시스템(Direct system): 수출국 배송센터에서 해외 자회사의 고객 또는 최종 소비자·판매점에 직송한다. 주로 항공운송을 이용하고 자회사는 물류에 직접 관여하지 않는다.","src":"기출 2026-3"},{"t":"통과형 시스템(Transit system): 해외 자회사 창고는 보관보다 집하·분류·배송 중심의 통과센터. 수출국에 재고를 집중하고 출하 빈도가 높다.","src":"기출 2024-8 | 기출 2025-3 | 보충"},{"t":"다국가 창고 시스템(Multi-country warehouse system): 지역물류거점(허브 창고)을 두고 동일 경제권 내 각국 자회사 창고·고객에 분배한다. 로테르담·싱가포르 같은 교통 중심지에 입지한다.","src":"기출 2023-18 | 기출 2021-3"},{"t":"다국가 창고 시스템 흐름: 생산국 → 해외 거점(허브) 창고 → 각국 자회사 창고 또는 고객.","src":"기출 2025-3 | 기출 2022-2"},{"t":"허브창고 시스템: 고전적 시스템보다 재고량이 줄어 보관비가 절감된다. 생산공장에서 허브창고까지는 대량·저빈도 수송. 창고형·통과형 모두 사용 가능.","src":"기출 2021-3"},{"t":"허브창고 시스템의 단점: 허브창고에서 수송거리가 먼 자회사는 수송비 증가와 서비스수준 하락. 허브창고 입지는 지리적 서비스 범위뿐 아니라 수송의 편리성도 고려한다.","src":"기출 2021-3"},{"t":"허브 앤 스포크(Hub & Spoke): 선박·항공기 대형화에 따라 소수 대규모 거점 항만·공항으로 기항지를 줄이고, 소규모 거점은 피더서비스로 연결해 운송빈도를 줄이고 운송단위를 늘려 물류비를 절감한다.","src":"기출 2024-3"}]},{"머리":"국제물류 정보기술","줄":[{"t":"ITS(지능형교통시스템): 교통체계 구성요소에 전자·제어·통신 등 첨단기술을 접목해 유기적으로 작동하게 하는 차세대 교통시스템.","src":"기출 2023-25"},{"t":"CVO(화물운송정보시스템, Commercial Vehicle Operation): 배송계획 수립·자동배차, 차량 실시간 위치관제, 화물위치 추적·도착예정시간 제공. 조직 간 표준화 전자문서 교환은 EDI이다.","src":"기출 2023-25 | 기출 2024-28"},{"t":"WMS: 제품 입고·집하·적재·출하 작업과 관련 데이터의 자동처리 시스템.","src":"기출 2023-25"},{"t":"DPS(디지털 피킹 시스템): 랙·보관구역에 신호장치를 설치해 출고 화물의 위치와 수량을 알려준다.","src":"기출 2023-25"},{"t":"GPS: 인공위성 전파로 위치를 파악. 차량 위치추적·배차, 화주와 차주 실시간 알선, 택배 배송추적, 주문제품의 현재 상태·위치 실시간 제공.","src":"기출 2023-25 | 기출 2026-25"},{"t":"RFID(무선주파수 식별)·ECR·SCM·VMI·QR·POS·ERP는 선택지에 나온 다른 정보기술/물류관리 기법이다.","src":"기출 2024-3 | 기출 2024-28 | 기출 2026-25"}]}],"함정":[{"x":"현지물류체계는 본국 중심의 생산활동과 국제적으로 표준화된 판매활동이 이루 어진다.","o":"현지물류체계는 국가별 현지 자회사를 중심으로 현지국에 생산거점을 두고 생산·물류활동을 수행한다.","src":"기출 2022-1"},{"x":"수출국 창고에 재고를 집중시켜 운영할 수 있기 때문에 다른 어떤 시스템보다 보관비가 절감된다.","o":"수출국 창고에 재고를 집중해 보관비를 줄이는 것은 직송·통과형이다. 고전적 시스템은 해외 자회사 창고에 재고를 보관한다.","src":"기출 2022-2"},{"x":"수출기업으로부터 해외 자회사 창고로의 출하 빈도가 높기 때문에 해외 자회사 창고의 보관비가 상대적으로 절감된다.","o":"출하 빈도가 높아 보관비가 줄어드는 것은 통과형이다. 고전적 시스템은 대량·저빈도 출하로 운임을 줄인다.","src":"기출 2022-2"},{"x":"해외 자회사 창고는 집하ㆍ분류ㆍ배송기능에 중점을 둔다.","o":"집하·분류·배송에 중점을 두는 것은 통과형이다. 고전적 시스템의 자회사 창고는 보관기능 중심이다.","src":"기출 2022-2"},{"x":"상품이 생산국 창고에서 출하되어 한 지역의 중심국에 있는 중앙창고로 수송된 후 각 자회사 창고 혹은 고객에게 수송된다.","o":"생산국 창고에서 한 지역의 중심국 중앙창고로 수송한 뒤 각 자회사 창고·고객에게 보내는 것은 다국가 창고(거점창고) 시스템이다.","src":"기출 2022-2"},{"x":"혼재ㆍ대량수송을 통해 운송비용을 절감할 수 있다.","o":"혼재·대량수송으로 운송비를 절감하는 것은 고전적 시스템이다. 통과형은 다빈도 출하가 특징이다.","src":"기출 2024-8"},{"x":"상품이 생산국에서 해외 중앙창고로 출하된 후 각국 자회사 창고 혹은 고객에게 수송된다.","o":"생산국에서 해외 중앙(거점)창고로 출하한 뒤 각국 자회사 창고·고객에게 수송하는 것은 다국가 창고 시스템이다.","src":"기출 2024-8"},{"x":"해외 자회사는 상거래 유통에는 관여하지만 물류에는 직접적으로 관여하지 않는다.","o":"자회사가 물류에 직접 관여하지 않는 것은 직송 시스템이다. 통과형은 자회사 창고가 집하·분류·배송을 담당한다.","src":"기출 2024-8"},{"x":"수출입 통관수속을 고객이 직접 해야 하기 때문에 그만큼 고객 부담이 높아진다.","o":"수출입 통관수속을 고객이 직접 해야 해서 고객 부담이 커지는 것은 직송 시스템이다(보충).","src":"기출 2024-8"},{"x":"해외 자회사 창고는 보관기능 보다는 유통기능 및 통과센터로서의 기능이 강하다.","o":"유통기능·통과센터 기능이 강한 것은 통과형이다. 다국가 창고 시스템의 거점창고가 보관·분배를 담당한다.","src":"기출 2025-3"},{"x":"생산국의 창고에서 재고를 집중시켜 운영하므로 해외 자회사에서 보관비가 절감된다.","o":"생산국 창고에 재고를 집중해 해외 자회사 보관비를 줄이는 것은 통과형이다.","src":"기출 2025-3"},{"x":"해외 자회사는 상거래 유통에는 관여하지만 물류에는 직접적으로 관여하지 않는다.","o":"자회사가 물류에 직접 관여하지 않는 것은 직송 시스템이다.","src":"기출 2025-3"},{"x":"다빈도 출하가 이루어져 출하비, 운송비, 통관비 등이 증가할 수 있다.","o":"다빈도 출하로 출하비·운송비·통관비가 증가하는 것은 통과형이다. 다국가 창고 시스템은 거점창고로 대량 이송한다.","src":"기출 2025-3"}]},"#3":{"묶음":[{"머리":"무역계약의 청약과 승낙(CISG)","줄":[{"t":"CISG(국제물품매매계약에 관한 UN협약, 1980)의 적용 대상: 국제물품매매계약.","src":"기출 2024-33 | 보충"},{"t":"승낙: 청약에 대한 동의를 표시하는 진술이나 행위. 침묵·부작위는 그 자체만으로는 승낙이 되지 않는다(CISG 제18조).","src":"기출 2022-40 | 보충"},{"t":"승낙의 요건: 내용이 청약과 일치, 절대적·무조건적, 유효기간 내, 특정 청약에 대해 행해질 것. 문서로만 해야 하는 것은 아니다(구두·행위도 가능).","src":"기출 2025-35"},{"t":"승낙기간 계산: 서신에서 정한 기간은 서신에 표시된 일자(없으면 봉투 표시 일자)부터 계산한다.","src":"기출 2022-40"},{"t":"승낙기간 중 공휴일·비영업일은 기간에 산입한다. 다만 기간 말일이 청약자 영업소 소재지의 공휴일·비영업일이라 승낙통지가 도달할 수 없으면 다음 영업일까지 연장된다(CISG 제20조제2항).","src":"기출 2022-40 | 보충"},{"t":"기간이 지난 승낙(지연된 승낙)은 원칙적으로 계약을 성립시키지 못한다. 청약자가 지체 없이 승낙으로서 효력이 있다고 구두통지하거나 발송하는 경우에만 승낙의 효력이 있다(CISG 제21조).","src":"기출 2022-40 | 보충"},{"t":"승낙이 청약의 내용을 실질적으로 변경하지 않는 추가·상이 조건을 담으면 승낙이 될 수 있다. 대금·지급·물품의 품질·수량·인도장소·시기·당사자 책임범위·분쟁해결 관련 조건은 실질적 변경이어서 반대청약이 된다(CISG 제19조).","src":"기출 2022-40 | 보충"},{"t":"청약의 효력 소멸 사유: 승낙기간을 정하지 않은 청약에서 상당한 기간 내 승낙통지가 없을 때, 취소 불능 청약이라도 거절의 의사표시가 청약자에게 도달한 때.","src":"기출 2026-32 | 보충"},{"t":"피청약자의 승낙만으로 계약이 성립하지 않고 청약자의 최종확인이 있어야 구속력이 생기는 경우는 청약의 효력 소멸 사유가 아니라 확정 청약이 아닌 경우(조건부 청약)이다.","src":"기출 2026-32 | 보충"}]},{"머리":"CISG 매도인 계약위반에 대한 매수인 구제","줄":[{"t":"구제수단: 의무이행 청구, 대체물 인도 청구(물품 부적합이 본질적 계약위반인 경우), 하자보완(수리) 청구, 대금감액, 계약해제, 손해배상 청구.","src":"기출 2024-33 | 보충"},{"t":"권한쟁의 심판 청구는 CISG의 구제방법이 아니다(헌법재판 절차).","src":"기출 2024-33"}]},{"머리":"무역계약 조건: 수량·선적","줄":[{"t":"수량단위: 중량(ton·pound·kilogram)은 양곡·철강, 용적(CBM·barrel·bushel)은 액체·곡물류, 길이(meter·yard·inch)는 섬유·전선, 개수(piece·set·dozen)는 잡화·기계류, 포장(bale·drum·case)은 비료·밀가루 등.","src":"기출 2023-38"},{"t":"유리·합판·타일의 수량단위는 면적(㎡ 등)이다. CBM·barrel·bushel은 용적 단위이다.","src":"기출 2023-38 | 보충"},{"t":"분할선적(partial shipment): 약정 수량을 나누어 여러 번 선적하는 것. 계약에서 선적횟수와 수량을 구체적으로 나누어 약정한 경우는 할부선적(instalment shipment)이다.","src":"기출 2021-39 | 보충"},{"t":"UCP 600: 신용장이 분할선적을 금지하면 분할선적은 허용되지 않는다. 금지하지 않으면 허용된다.","src":"기출 2021-39 | 보충"},{"t":"UCP 600: 동일한 장소·일자·목적지, 동일한 특송업자가 서명한 둘 이상의 특송화물수령증 제시는 분할선적으로 보지 않는다.","src":"기출 2021-39"},{"t":"UCP 600: 신용장이 환적을 금지해도 물품이 컨테이너에 선적되고 선하증권이 환적이 행해질 수 있다고 표시하면 수리된다.","src":"기출 2021-39 | 보충"},{"t":"UCP 600: 환적이 금지된 신용장에서도 환적이 행해질 수 있다고 표시한 항공운송서류는 수리된다.","src":"기출 2021-39 | 보충"}]},{"머리":"신용장통일규칙(UCP 600) 운송서류","줄":[{"t":"항공운송서류의 요건: 운송인 명칭 표시 + 운송인 또는 지정대리인 서명, 운송을 위해 물품이 인수되었음 표시, 신용장에 명기된 출발공항·도착공항 표시, 발행일 표시, 신용장이 전통(full set) 원본을 요구하더라도 송화인용 원본이어야 한다.","src":"기출 2023-26 | 기출 2026-30 | 보충"},{"t":"대리인에 의한 서명은 그 대리인이 운송인을 대리하여 서명하였음을 표시해야 한다.","src":"기출 2026-30"},{"t":"항공운송서류는 명칭(AWB 등)이 어떠하든 요건을 충족하면 수리된다. 발행일 표시가 필요하다.","src":"기출 2023-26 | 보충"},{"t":"용선계약 선하증권(Charter party B/L): 선장 또는 지명된 대리인(agent), 또는 선박소유자(owner) 또는 지명된 대리인이 서명하여야 한다(UCP 600 제22조).","src":"기출 2023-27 | 보충"},{"t":"복합운송서류: 은행은 복합운송인 또는 그 대리인이 발행하고 상품의 발송·수취·선적이 명시된 운송서류를 수리한다(UCP 600 제19조).","src":"기출 2025-30 | 보충"}]},{"머리":"무역서류 약어","줄":[{"t":"Booking Note(선적예약확인서)·B/L(선화증권)·Manifest(적화목록)·Letter of Indemnity(파손화물보상장, L/I)는 선적지에서 발행한다. Letter of Guarantee(수입화물선취보증장, L/G)는 도착지에서 수입자가 선사에 제출한다.","src":"기출 2021-12"},{"t":"L/G(수입화물선취보증장): 선하증권보다 화물이 먼저 도착해 인수가 지연될 때 수하인이 화물을 인수하기 위해 사용하는 서류.","src":"기출 2026-10"},{"t":"M/R(본선수취증, Mate's Receipt): 본선에 화물을 선적한 후 1등항해사가 발행하는 서류. 선하증권 발행의 근거.","src":"기출 2026-10"},{"t":"S/R(선적요청서)은 송화인이 선사에 제출하는 서류, D/O(화물인도지시서)는 선사가 수하인에게 발급해 화물 인도를 지시하는 서류, D/R(부두수취증)은 컨테이너 운항 선사가 화주로부터 화물을 수취했을 때의 수령증.","src":"보충 | 기출 2026-27"},{"t":"CLP(Container Load Plan, 컨테이너 내부 적부도): 컨테이너 내부 화물의 적재 위치도.","src":"기출 2021-23 | 기출 2026-27"}]}],"함정":[{"x":"계약에서 선적횟수와 선적수량을 구체적으로 나누어 약정한 경우를 분할선적 이라고 한다.","o":"계약에서 선적횟수와 선적수량을 구체적으로 나누어 약정한 경우는 할부선적이다. 분할선적은 약정 수량을 나누어 여러 번 선적하는 것이다.","src":"기출 2021-39"},{"x":"UCP 600에서는 신용장이 분할선적을 금지하고 있더라도 분할선적은 허용된다.","o":"UCP 600에서 신용장이 분할선적을 금지하면 분할선적은 허용되지 않는다.","src":"기출 2021-39"},{"x":"UCP 600에서는 신용장이 환적을 금지하고 있다면 물품이 선화증권에 입증된 대로 컨테이너에 선적된 경우라도 환적은 허용되지 않는다.","o":"UCP 600에서 신용장이 환적을 금지해도 물품이 선하증권에 입증된 대로 컨테이너에 선적된 경우 환적이 허용된다.","src":"기출 2021-39"},{"x":"UCP 600에서는 신용장이 환적을 금지하고 있는 경우에는 환적이 행해질 수 있다고 표시하고 있는 항공운송서류는 수리되지 않는다.","o":"UCP 600에서 신용장이 환적을 금지하더라도 환적이 행해질 수 있다고 표시한 항공운송서류는 수리된다.","src":"기출 2021-39"},{"x":"분쟁해결에 관한 부가적 조건을 포함하고 있는 청약에 대한 회답은 승낙을 의도 하고 있는 경우 승낙이 될 수 있다.","o":"분쟁해결에 관한 조건을 변경하는 회답은 청약 내용을 실질적으로 변경하는 것이어서 승낙이 되지 못하고 반대청약이 된다(CISG 제19조).","src":"기출 2022-40"},{"x":"청약에 대한 동의를 표시하는 상대방의 진술뿐만 아니라 침묵 또는 부작위는 그 자체만으로 승낙이 된다.","o":"침묵 또는 부작위는 그 자체만으로는 승낙이 되지 않는다(CISG 제18조).","src":"기출 2022-40"},{"x":"승낙을 위한 기간이 경과한 승낙은 당사자 간의 별도의 합의가 없더라도 원칙적 으로 계약을 성립시킬 수 있다.","o":"승낙기간이 지난 승낙은 원칙적으로 계약을 성립시키지 못한다(청약자가 지체 없이 효력을 인정한다고 통지한 경우만 예외).","src":"기출 2022-40"},{"x":"승낙기간 중 기간의 말일이 승낙자 영업소 소재지의 공휴일 또는 비영업일에 해 당하여 승낙의 통지가 기간의 말일에 청약자에게 도달할 수 없는 경우에도 공휴 일 또는 비영업일은 승낙기간의 계산에 산입한다.","o":"기간 말일이 청약자 영업소 소재지의 공휴일·비영업일이어서 승낙통지가 도달할 수 없으면 기간은 다음 영업일까지 연장된다.","src":"기출 2022-40"},{"x":"승낙은 문서로만 행해져야 한다.","o":"승낙은 문서·구두·행위 등 방식에 제한이 없다.","src":"기출 2025-35"}]},"#4":{"묶음":[{"머리":"규칙의 성격과 구조","줄":[{"t":"Incoterms 2020은 매매계약 자체가 아니다. 매매계약에 편입해서 사용하는 규칙이다.","src":"기출 2024-32"},{"t":"11개 규칙을 2그룹으로 나눈다: 모든 운송방식용 7개(EXW·FCA·CPT·CIP·DAP·DPU·DDP), 해상·내수로 운송용 4개(FAS·FOB·CFR·CIF).","src":"기출 2025-37 | 기출 2024-34 | 보충"},{"t":"해상·내수로 운송에만 사용: FAS, FOB, CFR, CIF.","src":"기출 2024-34"},{"t":"당사자 의무조항 A1~A10(매도인)과 B1~B10(매수인)을 나란히 배열하는 수평적 체제(Horizontal Format).","src":"기출 2025-37 | 기출 2025-40"},{"t":"매도인 의무 항목: A1 General obligations, A2 Delivery, A3 Transfer of risks, A4 Carriage, A5 Insurance, A6 Delivery/transport document, A7 Export/import clearance, A8 Checking/packaging/marking, A9 Allocation of costs, A10 Notices. 'Taking delivery'는 매수인 측 항목(B2)이다.","src":"기출 2026-38 | 보충"},{"t":"Incoterms가 다루는 것: 매도인·매수인의 의무, 비용, 위험, 물품 인도 장소와 시점.","src":"기출 2022-37 | 기출 2023-33 | 기출 2024-36"},{"t":"Incoterms가 다루지 않는 것: 매매물품의 소유권·물권 이전, 매매계약 위반에 대한 구제수단, 계약상 의무이행의 지체 등 위반의 효과, 관세 부과, 대금지급의 시기·장소·방법, 분쟁해결 방법·장소·준거법.","src":"기출 2022-37 | 기출 2023-33 | 기출 2024-36 | 기출 2026-39"}]},{"머리":"Incoterms 2020 개정 내용","줄":[{"t":"FCA, DAP, DPU, DDP에서 매수인 또는 매도인 자신의 운송수단으로 운송하는 것을 허용한다. (FCA는 매수인 자신의 운송수단, DAP·DPU·DDP는 매도인 자신의 운송수단)","src":"기출 2021-32 | 기출 2023-32 | 기출 2025-40"},{"t":"FCA에서 매수인이 운송인에게 본선적재 표기가 있는 선하증권을 매도인에게 발행하도록 지시할 수 있는 옵션을 신설했다.","src":"기출 2023-32 | 기출 2025-40"},{"t":"DAT를 DPU로 개정했다. 목적지는 터미널에 한정되지 않고 어떤 장소든 될 수 있다는 점을 강조한다. DAT와 DAP의 배열을 바꿔, 양하 전에 인도가 이루어지는 DAP가 DPU 앞에 온다. (DAF가 아니라 DAT가 DPU로 변경)","src":"기출 2021-32 | 기출 2023-34 | 기출 2025-40"},{"t":"보험: CIF는 ICC(C) 최소담보, CIP는 ICC(A) 최대담보가 기본이다. (CIF 최대담보·CIP 최소담보가 아니다) 당사자 합의로 달리 정할 수 있다.","src":"기출 2021-35 | 기출 2023-32 | 기출 2025-40"},{"t":"운송의무·보험비용 조항에 보안 관련 요건을 삽입했다.","src":"기출 2023-32 | 기출 2026-39"},{"t":"사용지침(Guidance Note)을 설명문(Explanatory Note)으로 변경했다.","src":"기출 2023-32"},{"t":"2020 개정 중 소유권 이전, 계약위반 구제수단, 이행지체 효과는 개정 내용이 아니다(애초에 다루지 않는다).","src":"기출 2026-39"}]},{"머리":"규칙별 인도·위험 이전 시점","줄":[{"t":"EXW(공장인도): 매도인이 영업구내 등 합의된 장소에서 물품(수출통관 안 하고, 수취용 운송수단에 적재하지 않은 상태)을 매수인의 처분 하에 둘 때 인도. 지정인도장소 내 복수 지점이 있으면 매도인이 가장 적합한 지점을 선택. 국내거래에 적합.","src":"기출 2024-32 | 기출 2022-32 | 기출 2026-40"},{"t":"FCA(운송인인도): 매도인이 매수인이 지정한 운송인(또는 제3자)에게 물품을 인도. 인도장소가 매도인 구내이면 매수인이 마련한 운송수단에 적재해 인도. 구내가 아닌 장소이면 도착한 매도인의 운송수단에 실린 채 양하 준비된 상태로 인도하고 양하 의무는 없다. 인도장소만 지정해도 되고, 정확한 지점을 특정하지 않아도 된다.","src":"기출 2021-36 | 기출 2022-32 | 기출 2026-40"},{"t":"CPT·CIP: 매도인이 자기가 계약한 운송인에게 물품을 인도할 때(또는 그렇게 인도된 물품을 조달) 위험 이전. 매도인이 운송계약을 체결하고 운임 지급(CIP는 보험 포함).","src":"기출 2022-32 | 기출 2024-38"},{"t":"FAS(선측인도): 지정 선적항에서 매수인이 지정한 선박의 선측에 물품이 놓인 때 인도·위험 이전.","src":"기출 2024-32 | 기출 2025-37"},{"t":"FOB(본선인도): 지정 선적항에서 매수인이 지정한 선박에 적재하여 인도(적재된 때 위험 이전). 매수인이 운송계약을 체결. 목적항 양하비용은 매수인이 부담.","src":"기출 2022-32 | 기출 2021-36 | 기출 2025-37"},{"t":"FOB: 매수인이 지정한 선박이 물품을 수령하지 않은 경우, 물품이 계약물품으로 특정(clearly identified)된 경우에만 합의된 인도기일부터 매수인이 위험을 부담한다.","src":"기출 2021-32"},{"t":"CFR·CIF: 물품이 본선에 적재된 때 위험이 매도인에서 매수인으로 이전. 인도장소 합의가 없으면 인천→부산 피더선, 부산→롱비치 항양선박이면 인천항 선박 적재 시 위험 이전(최초 운송인에게 인도).","src":"기출 2021-32 | 기출 2024-32"},{"t":"DAP(도착지인도): 매도인이 지정목적지 또는 그 안의 합의된 지점에서 도착운송수단에 실어둔 채 양하 준비된 상태로 매수인의 처분 하에 둔다.","src":"기출 2024-32 | 기출 2025-37"},{"t":"DPU(도착지양하인도): 지정목적지에서 도착운송수단으로부터 양하(unload)하여 매수인의 처분 하에 둔다. 양하 의무가 있는 유일한 규칙. 양하비용은 매도인 부담.","src":"기출 2021-36 | 기출 2022-32 | 기출 2026-40"},{"t":"DDP(관세지급인도): 도착지에서 양하 준비된 상태로 인도하고 수입통관·수입관세·세금까지 매도인이 부담. 11개 규칙 중 매도인 의무가 최대.","src":"기출 2026-40"}]},{"머리":"양하비용·통관·검사 비용 부담","줄":[{"t":"CPT에서 운송계약상 목적지 양하비용을 매도인이 부담하기로 한 경우 매도인이 부담한다.","src":"기출 2021-36"},{"t":"DAP: 매도인이 운송계약에 따라 목적지 양하비용을 부담했다면, 별도 합의가 없으면 매수인에게서 회수할 수 없다.","src":"기출 2021-36"},{"t":"DAP는 목적지 양하비용 중 운송계약상 매도인이 부담하기로 된 비용만 부담하고, 수출국과 통과국(수입국 제외)의 통관절차와 비용을 부담한다.","src":"기출 2022-35"},{"t":"선적 전 검사비용: EXW는 매수인 부담, DDP는 매도인 부담.","src":"기출 2021-32"},{"t":"수출통관: EXW는 매수인이 하는 것이 원칙(매도인 협조). FCA·FAS·FOB·CFR·CIF·CPT·CIP·DAP·DPU·DDP는 매도인이 수출통관한다. 수입통관은 DDP만 매도인.","src":"보충"},{"t":"보험계약 기본: CIF는 ICC(C), CIP는 ICC(A). 부보금액은 계약금액의 110%가 기본(보충).","src":"기출 2021-35 | 보충"}]},{"머리":"CIF 수입가격 계산","줄":[{"t":"CIF 가격 = FOB 가격 + 해상운임 + 해상보험료. FOB 가격에는 공장~선적항 내륙운송비가 이미 포함된다.","src":"기출 2025-39"},{"t":"제외 항목: 도착항 수입통관비, 도착항~내륙기지 보세운송료(도착 후 비용).","src":"기출 2025-39"},{"t":"예: FOB 10,000 + 운임 500 + 보험 100 = CIF 10,600 (내륙운송비 70은 FOB에 포함, 통관비 20·보세운송료 100은 CIF 밖).","src":"기출 2025-39"}]},{"머리":"Incoterms 규칙 영문 정의(문구)","줄":[{"t":"CPT 정의: the seller delivers the goods—and transfers the risk—to the buyer by handing them over to the carrier contracted by the seller or by procuring the goods so delivered. The seller may do so by giving the carrier physical possession of the goods in the manner and at the place appropriate to the means of transport used.","src":"기출 2024-38"},{"t":"DPU: the only Incoterms rule that requires the seller to unload goods at destination. EXW: may be suitable for domestic trades. DDP: imposes on the seller the maximum level of obligation of all eleven rules. FCA: can be concluded naming only the place of delivery without specifying the precise point.","src":"기출 2026-40"}]},{"머리":"규칙별 운송계약·보험·통관 책임 요약","줄":[{"t":"운송계약 체결 의무: EXW·FCA·FAS·FOB는 매수인. CPT·CIP·CFR·CIF·DAP·DPU·DDP는 매도인.","src":"보충"},{"t":"보험계약 체결 의무: CIF·CIP만 매도인에게 있다. 나머지 규칙은 부보 의무가 없다(당사자가 필요에 따라 각자 부보).","src":"보충 | 기출 2021-35"},{"t":"위험은 수출지(운송인 인도 또는 본선 적재 시)에서 이전하지만 매도인이 운임(CIF·CIP는 보험료도)을 부담하는 규칙: CPT·CIP·CFR·CIF. 위험이 목적지에서 이전하는 규칙: DAP·DPU·DDP.","src":"보충"},{"t":"FCA에서 매수인은 자신이 지정한 운송인에게 본선적재 표기가 있는 선하증권을 매도인에게 발행하도록 지시할 수 있다(2020 신설 옵션).","src":"기출 2023-32 | 기출 2025-40"}]}],"함정":[{"x":"FOB규칙에서 매수인에 의해 지정된 선박이 물품을 수령하지 않은 경우 물품이 계약물품으로서 특정되어 있지 않더라도 합의된 인도기일부터 매수인은 위험을 부담한다.","o":"매수인이 지정한 선박이 물품을 수령하지 않은 경우, 물품이 계약물품으로 특정(clearly identified)된 경우에만 합의된 인도기일부터 매수인이 위험을 부담한다.","src":"기출 2021-32"},{"x":"DAP규칙에서 매도인이 운송계약에 따라 목적지에서 물품의 양륙비용을 부담한 경우 별도의 합의가 없다면 매수인으로부터 그 양륙비용을 회수할 수 있다.","o":"DAP에서 매도인이 운송계약에 따라 목적지 양하비용을 부담한 경우, 별도 합의가 없으면 매수인으로부터 회수할 수 없다.","src":"기출 2021-36"},{"x":"CPT 규칙에서 매도인은 지정선적항에서 매수인이 지정한 선박에 적재하여 인도 한다.","o":"CPT에서 매도인은 자신이 계약한 운송인에게 물품을 인도한다. 지정선적항에서 매수인 지정 선박에 적재하는 것은 FOB이다.","src":"기출 2022-32"},{"x":"DPU 규칙에서 매도인은 물품을 지정목적지에서 도착운송수단에 실어둔 채 양하 준비된 상태로 매수인의 처분 하에 둔다.","o":"DPU에서 매도인은 지정목적지에서 도착운송수단으로부터 양하(unload)한 물품을 매수인의 처분 하에 둔다. 양하 준비된 상태는 DAP이다.","src":"기출 2022-32"},{"x":"FOB 규칙에서 매수인이 운송계약을 체결할 의무를 가지고, 매도인은 매수인이 지정한 선박의 선측에 물품을 인도한다.","o":"FOB에서 매수인이 운송계약을 체결하고 매도인은 매수인이 지정한 선박에 적재하여 인도한다. 선측 인도는 FAS이다.","src":"기출 2022-32"},{"x":"FCA 규칙에서 지정된 물품 인도 장소가 매도인의 영업구내인 경우에는 물품을 수취용 차량에 적재하지 않은 채로 매수인의 처분 하에 둠으로써 인도한다.","o":"FCA에서 인도장소가 매도인의 영업구내이면 매수인이 마련한 수취용 운송수단에 적재하여 인도한다.","src":"기출 2022-32"},{"x":"CIF규칙은 최대담보조건, CIP규칙은 최소담보조건으로 보험에 부보하도록 개정 하였다.","o":"CIF는 ICC(C) 최소담보조건, CIP는 ICC(A) 최대담보조건으로 부보한다.","src":"기출 2023-32"},{"x":"Incoterms® 2020 규칙은 그 자체로 매매계약이다.","o":"Incoterms 2020 규칙은 매매계약 자체가 아니라 매매계약에 편입해서 사용하는 규칙이다.","src":"기출 2024-32"},{"x":"매도인의 의무사항 A1-A10을 먼저 나열한 후 매수인의 의무사항 B1-B10을 열거하고 있다.","o":"Incoterms 2020은 매도인 의무(A1-A10)와 매수인 의무(B1-B10)를 나란히 배열한 수평적 체제이다.","src":"기출 2025-37"},{"x":"EXW 규칙은 매도인이 자신의 영업장 또는 합의된 장소에서 매수인이 지정한 운송인이나 제3자의 처분 하에 놓인 때에 인도하는 것을 의미한다.","o":"EXW는 매도인이 영업구내 등 합의된 장소에서 물품을 매수인의 처분 하에 두는 때 인도되는 규칙이다.","src":"기출 2025-37"},{"x":"DPU 규칙은 지정목적지에서, 물품을 도착한 운송수단에서 양하준비된 상태로 매수인의 처분 하에 놓인 때 인도되는 것을 의미한다.","o":"DPU는 지정목적지에서 도착운송수단으로부터 양하된 물품이 매수인의 처분 하에 놓인 때 인도된다. 양하 준비된 상태로 두는 것은 DAP이다.","src":"기출 2025-37"},{"x":"FOB 규칙은 지정선적항에서 매수인이 지정한 선박의 선측에 물품이 놓인 때 인도되는 것을 의미한다.","o":"FOB는 지정선적항에서 매수인이 지정한 선박에 적재된 때 인도된다. 선측에 놓인 때 인도는 FAS이다.","src":"기출 2025-37"}]},"#5":{"묶음":[{"머리":"선박의 구조와 정의","줄":[{"t":"선박: 해상에서 사람 또는 물품을 싣고 운반하는 구조물. 부양성·적재성·이동성을 갖춘다.","src":"기출 2022-3"},{"t":"선박은 선체(hull)·기관·의장으로 구성된다. 용골(keel)은 선체 하부 중심의 뼈대 구조부이다.","src":"보충 | 기출 2023-13"},{"t":"선교(bridge): 선박 갑판 위에 설치되어 선장이 지휘하는 장소.","src":"기출 2023-13"},{"t":"발라스트(ballast): 공선 항해 시 선박의 감항성을 유지하려고 싣는 것. 주로 바닷물을 사용한다.","src":"기출 2023-13"},{"t":"건현(freeboard): 수중에 잠기지 않는 수면 위 선체의 높이.","src":"기출 2022-3"},{"t":"만재흘수선: 항행구역·시기에 따라 해수/담수, 동절기/하절기, 열대, 북태평양, 북대서양 등으로 구분해 선박의 우현 측에 표시한다.","src":"기출 2022-3"},{"t":"선급제도: 선박의 감항성(seaworthiness)에 관한 객관적·전문적 판단을 위해 생긴 제도. 선급을 얻으려면 선급검사관(surveyor)의 엄격한 감독 하에 선급규칙에 맞춰 건조되어야 한다.","src":"기출 2022-3 | 기출 2024-7"},{"t":"한국선급(KR)은 국제선급협회(IACS)의 정회원이고 영국 적하보험 선급약관에 등재되어 있다.","src":"기출 2024-7"}]},{"머리":"선박 톤수","줄":[{"t":"총톤수(Gross Tonnage, GT): 선박 내부의 총용적(밀폐된 전 공간). 관세·등록세·도선료 등의 부과기준.","src":"기출 2023-13 | 기출 2021-8 | 보충"},{"t":"순톤수(Net Tonnage, NT): 총톤수에서 기관실·선원실·해도실 등 선박운항 관련 장소의 용적을 뺀 것. 여객이나 화물의 수송에 직접 사용되는 용적. 톤세·항세·운하통과료·항만시설사용료 부과기준.","src":"기출 2021-8"},{"t":"배수톤수(Displacement Tonnage): 선체 수면 아래 부분의 배수용적에 상당하는 물의 중량.","src":"기출 2021-8"},{"t":"재화용적톤수(Measurement Tonnage): 화물선창 내 화물을 적재할 수 있는 총용적. 선박의 화물적재능력을 용적으로 표시.","src":"기출 2021-8"},{"t":"재화중량톤수(Dead Weight Tonnage, DWT): 만재흘수선에 상당하는 배수량과 경하배수량의 차이. 선박의 최대 적재능력(최대 허용 적재중량). 선박 매매·용선료의 기준.","src":"기출 2021-8 | 기출 2023-13 | 기출 2026-5"},{"t":"DWT는 관세·등록세·소득세·계선료·도선료 과세기준이 아니다.","src":"기출 2022-3"},{"t":"운하톤수(Canal Tonnage): 운하 통과료 산정 기준(선택지 등장).","src":"기출 2026-5"}]},{"머리":"선박의 종류","줄":[{"t":"RO-RO(Roll On/Roll Off) Ship: 선수·선미·선측에 램프(ramp)가 있어 트랙터·지게차 등으로 Drive On/Drive Off. 크레인 없이 자력으로 하역.","src":"기출 2021-15"},{"t":"LO-LO(Lift On/Lift Off) Ship: 크레인으로 수직 적양하. FO-FO(Float On/Float Off) Ship: 부양식 적양하(도크선 방식).","src":"기출 2021-15 | 보충"},{"t":"Geared Container Ship은 자체 하역장비(크레인) 보유, Gearless Container Ship은 보유하지 않는다.","src":"기출 2021-15 | 보충"}]},{"머리":"국제해사 관련 기구","줄":[{"t":"IMO(국제해사기구): 정부간 해사기술 협력, 해사안전·해양오염방지, 국제 법률문제 해결. UN 전문기구.","src":"기출 2021-6 | 기출 2025-23"},{"t":"FIATA(국제운송주선인협회연합): 국제운송인을 대표하는 비정부기구. 운송주선인 통합·권익보호·서류통일·표준거래조건 개발.","src":"기출 2021-6"},{"t":"ICS(국제해운회의소): 선주 이익증진 민간기구. 국제해운의 기술·법적 문제에 대한 선주 의견교환·정책입안.","src":"기출 2021-6 | 기출 2025-23"},{"t":"BIMCO(발틱국제해사협의회): 회원사 정보제공·자료발간, 선주 단합·용선제도 개선, 해운업계 친목과 이익.","src":"기출 2021-6 | 기출 2025-23"},{"t":"CMI(국제해사위원회): 해상법의 국제적 통일을 목적으로 하는 민간 국제기구. 해사산업 근로자 권익보호 기구도, 항로·항만시설 통일 UN전문기구도 아니다.","src":"기출 2021-6 | 기출 2025-23 | 보충"},{"t":"P&I Club(선주책임상호보험조합): 선박 사고에 대한 선주책임을 상호보험으로 담보.","src":"기출 2025-23"}]},{"머리":"해운 관련 제도","줄":[{"t":"편의치적(Flag of Convenience): 세금부담 경감·인건비 절감 등을 위해 소유 선박을 국적부여조건이 엄격하지 않은 외국에 등록. 조세회피국 국적 취득, 등록절차 간단, 자국 선원 승선 의무 없음, 안전기준 규제 약함, 재무상태·거래내역 보고의무와 기항지 제한이 없다.","src":"기출 2024-6 | 기출 2026-6"},{"t":"ISPS Code(국제선박항만보안규정): 선박과 항만시설에 영향을 미치는 보안위협을 탐지·제거.","src":"기출 2024-6 | 보충"},{"t":"항만국통제(PSC): 항만국이 자국 항구에 기항하는 외국국적 선박을 대상으로 국제협약 기준에 따라 점검·통제.","src":"기출 2024-6 | 보충"},{"t":"화물유보제도(Cargo Reservation): 자국선 보호·외화유출방지를 위해 자국 화물을 국적선이 운송하도록 하고, 국적선불취항증명서(waiver) 없이는 외국선 이용을 금지.","src":"기출 2024-6 | 보충"},{"t":"국적취득조건부 나용선(BBCHP): 외국 선박을 나용선한 뒤 용선기간이 끝나고 용선료를 모두 납부하면 자국 국적선으로 등록.","src":"기출 2024-6 | 보충"}]},{"머리":"해상운송의 특성","줄":[{"t":"해상운송의 장점: 대량화물의 장거리 수송, 단위당 저렴한 운송비, 자유로운 수송로, 전천후 운송수단.","src":"기출 2025-20 | 기출 2026-4"},{"t":"해상운송은 속도가 느리다. 문전수송(Door-to-Door)이 아니다.","src":"기출 2025-20 | 기출 2026-4"}]}],"함정":[{"x":"CMI는 선박의 항로, 항만시설 등을 통일하기 위해 설치된 UN전문기구이다.","o":"CMI(국제해사위원회)는 해상법의 국제적 통일을 목적으로 하는 민간 국제기구이다. 선박의 항로·항만시설 통일을 위한 UN전문기구가 아니다.","src":"기출 2021-6"},{"x":"총톤수(Gross Tonnage)는 선박이 직접 상행위에 사용되는 총 용적으로 주로 톤세, 항세, 운하통과료, 항만시설 사용료 등을 부과하는 기준이 되고 있다.","o":"톤세·항세·운하통과료·항만시설사용료 등의 부과기준이 되고 직접 상행위에 사용되는 용적을 나타내는 것은 순톤수이다. 총톤수는 선박 내부 총용적이다.","src":"기출 2021-8"},{"x":"재화중량톤수(DWT)는 관세, 등록세, 소득세, 계선료, 도선료 등의 과세기준이 된다.","o":"관세·등록세·도선료 등의 과세기준은 총톤수이다. 재화중량톤수(DWT)는 선박의 최대 적재능력으로 매매·용선료의 기준이다.","src":"기출 2022-3"},{"x":"선박은 선박의 외형과 이를 지탱하기 위한 선체와 선박에 추진력을 부여하는 용 골로 구분된다.","o":"선박은 선체·기관·의장으로 구성되며 용골(keel)은 선체 하부 중심의 구조부이다(보충).","src":"기출 2023-13"},{"x":"선박 및 항만설비에 영향을 미치는 보안위협을 탐지하고 제거하기 위한 제도이다.","o":"이 서술은 ISPS Code(국제선박항만시설보안규칙)에 관한 설명이다.","src":"기출 2024-6"},{"x":"항만국이 자국 항구에 기항하는 외국국적 선박을 대상으로 국제협약 상의 기준에 따른 점검 및 통제권한을 행사할 수 있도록 하는 제도이다.","o":"이 서술은 항만국통제(PSC)에 관한 설명이다.","src":"기출 2024-6"},{"x":"자국선 보호 및 외화유출방지를 위해 국적선취항지역은 국적선을 이용하도록 하고 국적선불취항증명서(waiver) 없이는 외국선 이용을 금지하는 제도이다.","o":"이 서술은 화물유보제도(Cargo Reservation)에 관한 설명이다.","src":"기출 2024-6"},{"x":"외국의 선박을 나용선한 뒤 용선기간이 종료되고 용선료를 모두 납부하면 자국의 국적선으로 등록하게 하는 제도이다.","o":"이 서술은 국적취득조건부 나용선(BBCHP)에 관한 설명이다. 편의치적은 소유 선박을 외국에 등록하는 제도이다.","src":"기출 2024-6"},{"x":"로이드 선급(Lloyd’s register)은 보험자들이 보험인수여부 및 보험료 산정을 위해 만든 선박등록부이다.","o":"출제 오답(바른 서술 미확인). 로이드 선급(Lloyd's Register)은 영국의 선급협회이다.","src":"기출 2024-7"},{"x":"재무상태, 거래내역을 보고해야 하며 기항지도 제한을 받는다.","o":"편의치적선은 재무상태·거래내역 보고의무가 없고 기항지 제한도 받지 않는다.","src":"기출 2026-6"}]},"#6":{"묶음":[{"머리":"정기선 운송의 특징","줄":[{"t":"정기선: 공시된 스케줄에 따라 고정 항로를 정기 운항한다. 항차마다 항로가 달라지지 않는다.","src":"기출 2022-5 | 기출 2025-22"},{"t":"운송계약: 개품운송계약(선하증권 발급, 별도 운송계약서 없음). 용선계약서(charter party)를 쓰지 않는다.","src":"기출 2023-12 | 기출 2025-22"},{"t":"개품운송계약은 불특정 다수의 화주를 대상으로 선박회사가 일방적으로 정한 정형화 약관을 화주가 포괄적으로 승인하는 부합계약. 요식계약이 아니다.","src":"기출 2022-4 | 기출 2023-14"},{"t":"운송인 성격: 공중운송인(Common/Public carrier). 불특정 다수 화주를 상대로 서비스.","src":"기출 2022-5 | 기출 2023-12"},{"t":"운임: 태리프(Tariff, 운임률표)를 공시하고 그에 따라 부과. 부정기선보다 안정적.","src":"기출 2022-5 | 기출 2023-14 | 기출 2023-12"},{"t":"운송화물: 이종화물(Heterogeneous cargo), 주로 단위화된 화물. 불특정 다수 화주로부터 집화하여 혼재운송.","src":"기출 2023-12 | 기출 2023-14 | 기출 2025-22"},{"t":"거액의 선대·시설·집화 투자가 필요하다. 해운시황에 따른 배선축소·항로 철수가 쉽지 않다.","src":"기출 2022-5 | 기출 2026-8"},{"t":"정기선에는 정박기간에 따른 체선료·조출료가 없다(그 개념은 부정기선·용선계약). 화주가 시기·항로를 요구하는 방식도 부정기선.","src":"기출 2026-8"},{"t":"정기선 관련 용어: tariff, shipping conference. charter party와 tramp는 부정기선 관련.","src":"기출 2024-10"}]},{"머리":"정기선 시장의 변화","줄":[{"t":"항로안정화협정·협의협정 체결 증가, 선사 간 전략적 제휴 증가, 선박 대형화, 블록체인 등 디지털 기술 도입.","src":"기출 2022-10"},{"t":"글로벌 공급망 확대로 서비스 범위는 확대된다(축소가 아님).","src":"기출 2022-10"},{"t":"미국 1998년 개정 해운법(OSRA): FMC에 대한 선사의 태리프 신고의무 폐지, 서비스계약(Service Contract) 허용(운임률·서비스 내용·내륙운송구간·손해배상 등 주요 내용 대외비 인정).","src":"기출 2022-7 | 보충"},{"t":"OSRA: 'me-too' 조항 삭제로 선사의 화주 차별대우 인정, NVOCC도 해상화물운송주선인과 같이 FMC 면허취득 의무화. 컨소시엄·전략적 제휴 등 공동행위는 허용.","src":"기출 2022-7"}]},{"머리":"정기선 운임과 할증료","줄":[{"t":"종가운임(Ad Valorem Freight): 화폐·보석·유가증권·미술품 등 고가품에 화물 가격을 기초로 일정률 징수.","src":"기출 2022-8"},{"t":"Open Rate(자유운임), Dual Rate(이중운임), Special Rate(특별운임), Pro Rata Freight(비례운임)는 선택지에 나온 다른 운임.","src":"기출 2022-8"},{"t":"FAK(Freight All Kinds Rate): 화물 종류를 불문하고 동일 운임. CCR(품목분류요율): 품목별 요율. Commodity Box Rate: 품목·컨테이너별.","src":"기출 2024-9 | 보충"},{"t":"THC(Terminal Handling Charge): 컨테이너화물이 CY에 반입되는 순간부터 본선 선측까지(또는 반대) 이동에 따르는 비용. 장척·벌크화물에 부과되는 운임이 아니다.","src":"기출 2024-9 | 기출 2025-17"},{"t":"Heavy Cargo Surcharge: 초과 중량에 따라 기본운임에 가산.","src":"기출 2025-17"},{"t":"Congestion Surcharge(체선할증료): 양륙항의 체선이 심해 장기간 정박이 요구되어 선사에 손해가 발생할 때 부과.","src":"기출 2025-17"},{"t":"BAF(Bunker Adjustment Factor): 벙커유 가격 인상에 따른 손실 보전. CAF(Currency Adjustment Factor): 환율변동에 따른 환차손 보전.","src":"기출 2025-17"},{"t":"Optional Surcharge(양륙항 선택 할증료): 최종 양륙항을 확정하지 않고 기항 순서에 따라 몇 개 항구를 기재한 뒤 화주가 도착 전에 양륙항을 선택하게 할 때 부과.","src":"기출 2023-16"},{"t":"Transhipment Additional Surcharge(환적 할증료), Port Congestion Surcharge(항만 혼잡 할증료)는 선택지에 나온 다른 할증료.","src":"기출 2023-16"}]},{"머리":"해운동맹과 정기선 시장 구조","줄":[{"t":"해운동맹(Shipping Conference): 정기선 선사들이 과당경쟁을 막으려고 운임·운항 조건을 협정하는 카르텔. 주요 수단은 운임협정, 공동계산, 이중운임제, 충성환급제, 투쟁선 등.","src":"보충"},{"t":"이중운임제(Dual Rate): 동맹 가입 선사에만 물량을 맡기는 화주에게 낮은 운임을 적용. 충성환급제(Deferred rebate)와 함께 화주를 묶는 수단.","src":"보충 | 기출 2022-8"},{"t":"컨소시엄·전략적 제휴: 선사 간 공동운항·선복교환으로 선박 대형화에 대응.","src":"기출 2022-10 | 기출 2022-7"},{"t":"UNCTAD 정기선동맹 행동규범(Liner Code, 1974)은 해운동맹 운영에 관한 조약이고 해상물품운송 책임 조약이 아니다.","src":"기출 2025-19 | 보충"}]}],"함정":[{"x":"항로가 일정하지 않고 매 항차마다 항로가 달라진다.","o":"정기선은 항로가 일정하고 공시된 스케줄에 따라 정기 운항한다.","src":"기출 2022-5"},{"x":"컨소시엄, 전략적 제휴 등 공동행위 및 경쟁제한 행위를 금지시켰다.","o":"미국 1998년 해운법 개정으로 컨소시엄·전략적 제휴 등 공동행위는 허용되었다.","src":"기출 2022-7"},{"x":"법적으로 요식계약(formal contract)의 성격을 가지고 있기 때문에 개별 화주와 운송계약서를 별도로 작성하여야 한다.","o":"개품운송계약은 불요식 계약이며 별도의 운송계약서 없이 선하증권을 발급한다.","src":"기출 2023-14"},{"x":"“Terminal Handling Charge”는 장척화물이나 벌크화물에 대해 부과되는 운임이다.","o":"Terminal Handling Charge는 CY 반입부터 본선 선측까지(또는 반대) 화물 이동 비용이다. 장척·벌크화물에 대한 운임이 아니다.","src":"기출 2025-17"},{"x":"고정된 운항일정과 항로가 없어 항로의 선택이 자유롭다.","o":"정기선은 고정된 운항일정과 항로가 있다.","src":"기출 2025-22"},{"x":"화주가 요구하는 시기와 항로에 따라 화물을 운송하는 방식이다.","o":"화주가 요구하는 시기와 항로에 따라 화물을 운송하는 방식은 부정기선이다. 정기선은 정해진 항로·일정에 따라 운항한다.","src":"기출 2026-8"},{"x":"해운시황에 따른 배선축소나 운항항로에서의 철수 등이 쉽다.","o":"정기선은 배선축소나 항로 철수가 쉽지 않다.","src":"기출 2026-8"},{"x":"운임이 해운시장에서 물동량과 선복량에 따라 변동하는 자유경쟁시장이다.","o":"해운시장의 물동량과 선복량에 따라 운임이 변동하는 자유경쟁시장은 부정기선이다. 정기선은 태리프 운임이다.","src":"기출 2026-8"},{"x":"정박기간에 따라 체선료와 조출료가 발생한다.","o":"정박기간에 따른 체선료·조출료는 부정기선(용선계약)에서 발생한다.","src":"기출 2026-8"}]},"#7":{"묶음":[{"머리":"용선계약의 종류","줄":[{"t":"항해용선(Voyage Charter): 특정 항구에서 다른 항구까지 화물운송을 위해 용선자와 선주 간 체결. 표준서식 Gencon. 용선계약에 의해 운송계약이 성립하고 용선계약서를 작성한다.","src":"기출 2021-14 | 기출 2021-10 | 기출 2025-25 | 기출 2022-4"},{"t":"항해용선 운임 계산: 화물 양에 따르는 물량용선(Freight Charter), 화물 양과 무관하게 본선 선복 기준의 총괄운임용선(Lump Sum Charter).","src":"기출 2022-4 | 기출 2026-7"},{"t":"정기용선(Time Charter): 일정기간 용선자가 선주로부터 선박운항권을 양도받고 기간으로 정한 용선료를 지급. 표준서식은 Gencon이 아니다(NYPE·Baltime 등).","src":"기출 2025-25 | 기출 2022-4 | 상법 제842조 | 보충"},{"t":"나용선(Bareboat Charter): 선박 자체만 용선, 용선자가 선장·선원을 고용하고 선비·운항비 일체를 부담하며 선박을 직접 점유.","src":"기출 2023-17 | 기출 2022-4 | 기출 2025-25"},{"t":"Gross Term Charter(Berth/Liner/Gross term): 선주가 적·양하항의 하역비와 항비 일체를 부담.","src":"기출 2022-4 | 기출 2025-25"},{"t":"Partial charter(일부용선): 선복 일부만 용선. COA(Contract of Affreightment): 일정 기간 동안 일정량을 여러 항차에 나누어 운송하기로 하는 계약으로, 1항차 계약이 아니다. 특정 선박을 지정하지 않는다.","src":"기출 2023-17 | 기출 2025-25 | 보충"},{"t":"부정기선: 항로와 운항일정을 화주가 자유롭게 선택(용선계약 따라). 공표 운임이 아니라 시황에 따라 운임이 정해진다. 곡물·광석·유류 등 산화물(Bulk cargo)을 대량으로 운송, 운임부담능력이 작거나 부가가치가 낮은 화물에 적합.","src":"기출 2021-10 | 기출 2026-8"},{"t":"상법: 항해용선계약은 선박소유자가 선원이 승무하고 항해장비를 갖춘 선박의 전부 또는 일부를 물건 운송에 제공하기로 약정하고 용선자가 운임을 지급하기로 약정함으로써 효력이 생긴다.","src":"상법 제827조제1항"},{"t":"상법: 정기용선계약은 선박소유자가 용선자에게 선원이 승무하고 항해장비를 갖춘 선박을 일정 기간 항해에 사용하게 할 것을 약정하고 용선자가 기간으로 정한 용선료를 지급하기로 약정함으로써 효력이 생긴다.","src":"상법 제842조"}]},{"머리":"하역비 부담 조건","줄":[{"t":"Berth(Liner) Term: 선적·양하 하역비 모두 선주 부담. Gross Term과 같다.","src":"기출 2022-6 | 기출 2022-4"},{"t":"FI(Free In): 선적비는 화주(용선자) 부담, 양하비는 선주 부담.","src":"기출 2022-6"},{"t":"FO(Free Out): 선적비는 선주, 양하비는 화주 부담.","src":"기출 2022-6"},{"t":"FIO(Free In and Out): 선적·양하 하역비 모두 용선자(화주) 부담. FIOST: FIO에 stowed(적부)·trimmed(평준작업)까지 용선자 부담.","src":"기출 2022-6 | 기출 2025-21 | 보충"},{"t":"양하 시 하역비를 화주가 부담하지 않는 조건은 Berth Term과 FI Term이다.","src":"기출 2022-6"}]},{"머리":"정박기간(Laytime)과 체선료·조출료","줄":[{"t":"정박기간(Laytime): 용선자가 하역을 완료해야 하는 허용 기간. 초과하면 Demurrage, 절약하면 Dispatch Money.","src":"기출 2021-14"},{"t":"Demurrage(체선료): 초과정박일수에 대해 용선자가 선주에게 지급하기로 한 일종의 벌과금.","src":"기출 2021-14"},{"t":"Dispatch Money(조출료): 약정 정박기간보다 빨리 하역이 완료되었을 때 절약된 기간에 대해 선주가 용선자에게 지급하는 보수.","src":"기출 2021-14"},{"t":"CQD(Customary Quick Despatch): 해당 항구의 관습적 하역방법·하역능력에 따라 가능한 빨리 하역. 일요일·공휴일 작업일수는 관습에 따라 정박기간에 산입된다.","src":"기출 2021-14 | 기출 2024-13 | 보충"},{"t":"Running Laydays: 하역개시일부터 종료일까지 연속된 모든 일수를 정박기간에 산입. 우천·동맹파업·불가항력 등으로 하역하지 못한 날도 제외하지 않는다. 특약이 없으면 일요일·공휴일에 작업해도 모두 포함.","src":"기출 2021-14 | 기출 2024-13"},{"t":"WWD(Weather Working Days): 하역이 가능한 기상조건의 작업일만 정박기간에 포함.","src":"기출 2024-13"},{"t":"WWDSHEX: 일요일과 공휴일을 제외. 일요일·공휴일에 작업해도 정박기간에서 제외.","src":"기출 2024-13"},{"t":"WWDSHEXUU(Unless Used): 일요일·공휴일에 작업하면 그 시간은 정박기간에 포함.","src":"기출 2024-13"},{"t":"체선료 계산 예(2026 기출): 양륙정박기간 5일, Running Laydays, NOR 10/1 오후, 하역완료 10/8 오후, 체선료 US$3,000/일 → 초과 2일(10/7·10/8) × 3,000 = US$6,000.","src":"기출 2026-9"},{"t":"정박시간표(time sheet) 기재사항: 도착일시·접안일시, 하역준비완료일시·하역준비완료통지서(NOR) 제출일시, 하역개시일시·하역실시기간, 약정 하역률과 허용정박기간. '7일 하역량 및 누계'는 기재사항이 아니다.","src":"기출 2022-11"}]},{"머리":"항해용선계약 약관","줄":[{"t":"Cancelling Clause: 용선선박이 용선계약에 명시된 날짜까지 선적준비를 하지 못하면 용선자에게 계약 취소 여부의 선택권을 부여.","src":"기출 2024-5"},{"t":"Not Before Clause: 선박이 도착예정일보다 늦거나 빨리 도착하면 부선료·하역대기료 등으로 화주에게 손실이 생기므로, 선박이 선적준비완료 예정일 이전에 도착해도 하역하지 않는다는 조항.","src":"기출 2024-15"},{"t":"항해용선계약에 포함되는 것: Laytime, Demurrage, Cancelling Date, Despatch Money. Off Hire는 정기용선계약 조항.","src":"기출 2022-9"},{"t":"Lien Clause(유치권), General Average Clause(공동해손)는 선택지에 나온 다른 약관.","src":"기출 2024-15"},{"t":"Gencon Part II: 선박에 관습적으로 부과되는 부과금·비용·세금은 선주(Owners)가 부담하고, 화물에 관습적으로 부과되는 부과금·관세·세금은 용선자(Charterers)가 부담.","src":"기출 2026-11"}]},{"머리":"부정기선 운임","줄":[{"t":"Lump Sum Freight(선복·일괄운임): 화물의 개수·중량·용적과 관계없이 항해 또는 선복을 단위로 일괄 부과.","src":"기출 2021-9 | 기출 2023-20 | 기출 2024-26"},{"t":"Dead Freight(공적운임): 선적하기로 약정한 화물량보다 실제 선적량이 적으면 용선자가 부족분에 대해 선주에게 지급.","src":"기출 2022-12 | 기출 2025-18"},{"t":"Long Term Contract Freight: 원유·철광석 등 대량화물 수요를 가진 대기업과 선사 간에 장기간 반복 항해에 적용하는 운임.","src":"기출 2023-20"},{"t":"Forward rate: 용선계약 체결 시 화물을 장기간이 지난 뒤 적재하기로 할 때 미리 합의하는 운임.","src":"기출 2021-9"},{"t":"Back freight: 화물이 목적항에 도착했으나 수화인이 인수를 거절하거나 목적항 사정으로 양륙할 수 없어 다른 곳으로 운송하거나 반송할 때 적용되는 운임.","src":"기출 2021-9"},{"t":"Pro rata freight(비례운임): 선박이 운송 도중 불가항력 등으로 목적항까지 운송을 계속하지 못하고 중간에서 화물을 인도할 때, 운송한 비율에 따라 지급하는 운임. 목적항 변경 시 부과하는 운임이 아니다.","src":"기출 2021-9 | 보충"},{"t":"Optional charge: 선적 시 양륙항이 확정되지 않아 화주가 여러 항구 중 선택할 권리가 있는 화물에 부과하는 할증요금.","src":"기출 2021-9"},{"t":"Freight All Kinds Rate, Consecutive Voyage Freight(연속항해운임), Congestion Surcharge는 선택지에 나온 다른 운임.","src":"기출 2023-20 | 기출 2022-12"},{"t":"Advance Freight(선불운임), Lump Sum, Pro Rate, Back freight는 Dead Freight와 구별.","src":"기출 2025-18"}]},{"머리":"정기용선과 항해용선의 비교","줄":[{"t":"항해용선: 항해(트립) 단위 계약, 운임은 화물량·선복 기준. 선주가 선박 운항·선원·연료·항비를 부담(Gross Term 기준). 표준서식 Gencon.","src":"기출 2022-4 | 기출 2025-25 | 보충"},{"t":"정기용선: 기간 단위 계약, 용선료는 기간으로 정한다. 선주는 선원 유지·선박 보수·보험, 용선자는 연료·항비·하역비 부담이 통례. 용선자가 운항권을 갖는다. 선박이 가동하지 못한 기간은 Off Hire(용선료 지급 정지).","src":"기출 2025-25 | 기출 2022-9 | 보충"},{"t":"나용선: 선박만 임차, 용선자가 선원 고용과 운항 일체. 선박을 직접 점유한다.","src":"기출 2023-17 | 기출 2025-25"}]}],"함정":[{"x":"선박회사 간의 과다한 운임경쟁을 막기 위해 공표된 운임을 적용하는 것이 일반적 이다.","o":"공표된 운임(태리프)을 적용하는 것은 정기선의 특징이다. 용선계약(부정기선)은 시황과 계약에 따라 운임이 정해진다.","src":"기출 2021-10"},{"x":"Running Laydays는 하역개시일부터 종료일까지 모든 일수를 정박기간에 산입 하지만 우천시, 동맹파업 및 기타 불가항력 등으로 하역을 하지 못한 경우 정박 기간에서 제외하는 조건이다.","o":"Running Laydays는 하역개시일부터 종료일까지 연속된 모든 일수를 산입하며, 우천·동맹파업·불가항력으로 하역하지 못한 날도 정박기간에서 제외하지 않는다.","src":"기출 2021-14"},{"x":"정기용선계약은 일정 기간을 정해 용선자에게 선박을 사용하도록 하는 계약으로 표준서식으로 Gencon 서식이 사용된다.","o":"정기용선계약의 표준서식은 NYPE·Baltime 등이다. Gencon은 항해용선계약 표준서식이다.","src":"기출 2022-4"},{"x":"CQD는 항구의 관습적 하역방법이나 하역능력 등에 따라 가능한 한 빨리 하역하 도록 약정하는 것으로, 일요일과 공휴일에 작업을 하면 모두 정박기간에서 제외 한다.","o":"CQD에서는 일요일·공휴일에 작업한 경우 그 일수가 정박기간에 산입된다. 일요일·공휴일 작업분까지 제외하는 것은 WWDSHEX이다.","src":"기출 2024-13 | 보충"},{"x":"“Contract of Affreightment”는 계약조항 및 조건에 있어서 1항차 항해용선계약 내용의 대부분을 그대로 유지하는 계약이다.","o":"Contract of Affreightment(COA)는 일정 기간 동안 일정량의 화물을 여러 항차에 나누어 운송하기로 하는 계약이다(1항차 계약이라는 서술이 오답).","src":"기출 2025-25"}]},"#8":{"묶음":[{"머리":"선하증권의 기능과 법적 성질","줄":[{"t":"기능: 운송물 수령증, 운송계약의 증거(추정적 증거), 운송물 인도청구권을 표창하는 권리증권(유가증권).","src":"보충 | 상법 제854조"},{"t":"요식증권: 법정기재사항을 갖추어야 한다(상법·준거법). 법정 형식을 요한다.","src":"기출 2022-24 | 기출 2026-12"},{"t":"요인증권: 선사가 화물의 수령 또는 선적에 근거하여 발급.","src":"기출 2026-12"},{"t":"문언증권: 선주와 화주의 권리·의무는 증권에 기재된 문언에 따라 정해진다.","src":"기출 2026-12"},{"t":"지시증권·유통증권: 권리자로 지정된 자가 배서로 양도. 배서 양도에 의해 소유권이 이전된다.","src":"기출 2022-24 | 기출 2026-12"},{"t":"채권증권: 정당한 소지인이 발급한 운송인에게 물품 인도를 청구. 대표증권(운송물 대표). 처분증권·인도증권 성질도 있다.","src":"기출 2022-24 | 기출 2026-12 | 보충"},{"t":"상환증권(제시증권): 증권과 상환으로 물품 인도를 청구한다.","src":"기출 2025-12 | 보충"}]},{"머리":"선하증권의 종류","줄":[{"t":"Straight B/L(기명식): 수하인란에 수하인의 상호 및 주소가 기재되어 권리가 수하인에게 귀속. 유통 불가.","src":"기출 2021-11 | 기출 2026-23"},{"t":"Order B/L(지시식): 수하인란에 지시인 기재, 배서로 양도 가능.","src":"기출 2021-11 | 보충"},{"t":"Surrendered B/L: 권리증권 기능을 포기하고 원본 없이 전송받은 사본으로 화물을 인수.","src":"기출 2021-11"},{"t":"Third Party B/L: 송화인란에 수출상이 아닌 제3자를 송화인으로 표시.","src":"기출 2021-11"},{"t":"Switch B/L, Groupage(House) B/L, Short form B/L, Charter Party B/L은 다른 종류의 B/L.","src":"기출 2021-11 | 보충"},{"t":"Clean B/L: 물품이 본선 적재 시 하자가 없을 때 발행. 반대는 Foul(Dirty) B/L.","src":"기출 2026-23 | 보충"},{"t":"Shipped(On board) B/L: 화물이 특정 선박에 선적되었음을 명시. Received B/L은 선적 전 수취 시점에 발행.","src":"기출 2026-23 | 보충"},{"t":"Stale B/L: 선적일로부터 21일이 경과한 B/L(UCP 600은 선적일 후 21일 이내 제시를 요구).","src":"기출 2026-23 | 보충"},{"t":"Through B/L: 해상을 포함하는 2개 이상 운송방식을 이용하여 최초 운송인(선주)이 다른 선박회사 선박을 이용할 때 최초 운송인이 전 구간 운송에 대하여 책임지는 B/L.","src":"기출 2026-23"},{"t":"신용장 문구 해석: full set = 전통(통상 3통 1조), ocean B/L = 해상/내수로 운송, to the order of shipper = 유통성(송하인 지시), freight collect = 운임 후불(선불 아님), notify accountee = 착하통지처를 신용장 대금 지급인인 수입업자로 표시.","src":"기출 2026-29"}]},{"머리":"선하증권 기재사항","줄":[{"t":"상법 선하증권 법정기재사항 12가지: ①선박의 명칭·국적·톤수 ②송하인이 서면으로 통지한 운송물의 종류·중량 또는 용적·포장의 종별·개수와 기호 ③운송물의 외관상태 ④용선자 또는 송하인의 성명·상호 ⑤수하인 또는 통지수령인의 성명·상호 ⑥선적항 ⑦양륙항 ⑧운임 ⑨발행지와 발행연월일 ⑩수통의 선하증권을 발행한 때 그 수 ⑪운송인의 성명 또는 상호 ⑫운송인의 주된 영업소 소재지. 운송인이 기명날인 또는 서명한다.","src":"상법 제853조제1항"},{"t":"운송물의 중량·용적·개수·기호가 실제 수령한 운송물과 맞지 않는다고 의심할 상당한 이유가 있거나 확인할 방법이 없으면 그 기재를 생략할 수 있다.","src":"상법 제853조제2항"},{"t":"송하인은 제2호 기재사항이 정확함을 운송인에게 담보한 것으로 본다.","src":"상법 제853조제3항"},{"t":"운송인이 선하증권에 기재된 통지수령인에게 통지하면 송하인·선하증권소지인·그 밖의 수하인에게 통지한 것으로 본다.","src":"상법 제853조제4항"},{"t":"임의 기재사항 예: 면책조항, 선하증권 번호. (선박 명칭, 송하인은 법정기재사항)","src":"기출 2025-29 | 상법 제853조"},{"t":"선하증권 법정기재사항에 운임지불지·환율, 선하증권번호, 본선항해번호는 없다.","src":"기출 2024-27 | 상법 제853조"},{"t":"헤이그규칙상 선화증권 법정기재사항: 화물 식별에 필요한 주요한 화인(마크), 송화인이 서면으로 제출한 포장 수·개수·수량 또는 중량, 물품의 외관상태.","src":"기출 2021-25"},{"t":"2021 기출의 헤이그규칙 정답 조합에는 발행지·원본 수·송화인 명칭이 들어가지 않았다. 이 셋은 상법 제853조 기재사항이다.","src":"기출 2021-25 | 상법 제853조"}]},{"머리":"선하증권의 발행과 효력(상법)","줄":[{"t":"운송인은 운송물을 수령한 후 송하인의 청구에 의하여 1통 또는 수통의 선하증권을 교부하여야 한다(수령선하증권).","src":"상법 제852조제1항"},{"t":"운송인은 운송물을 선적한 후 송하인의 청구에 의하여 선적선하증권을 교부하거나 수령선하증권에 선적의 뜻을 표시하여야 한다.","src":"상법 제852조제2항"},{"t":"운송인은 선장 또는 그 밖의 대리인에게 선하증권의 교부 또는 선적 표시를 위임할 수 있다.","src":"상법 제852조제3항"},{"t":"선하증권이 발행되면 운송인과 송하인 사이에 선하증권에 기재된 대로 개품운송계약이 체결되고 운송물을 수령 또는 선적한 것으로 추정한다.","src":"상법 제854조제1항"},{"t":"선의로 취득한 소지인에 대하여 운송인은 선하증권에 기재된 대로 운송물을 수령 혹은 선적한 것으로 보고, 기재된 바에 따라 운송인으로서 책임을 진다.","src":"상법 제854조제2항"},{"t":"용선자의 청구가 있으면 선박소유자는 운송물을 수령한 후 선하증권을 발행한다. 제3자가 선의로 취득하면 선박소유자는 제854조제2항에 따라 운송인으로서 권리와 의무가 있다.","src":"상법 제855조제1항·제3항"},{"t":"양륙항에서 수통의 선하증권 중 1통을 소지한 자가 인도를 청구해도 선장은 거부하지 못하고, 1통의 소지인이 인도를 받으면 다른 선하증권은 효력을 잃는다.","src":"상법 제857조"},{"t":"선하증권의 교부를 받은 용선자·송하인은 발행자의 청구가 있으면 선하증권 등본에 기명날인 또는 서명하여 교부하여야 한다.","src":"상법 제856조"},{"t":"전자선하증권: 송하인 또는 용선자의 동의를 받아 법무부장관이 지정한 등록기관에 등록하는 방식으로 발행하며 종이 선하증권과 동일한 법적 효력이 있다. 운송인이 전자서명으로 송신하고 용선자·송하인이 수신해야 효력이 생기며, 배서의 뜻을 기재한 전자문서를 등록기관을 통해 송신하는 방식으로 양도한다.","src":"상법 제862조"},{"t":"운송인의 송하인·수하인에 대한 채권·채무는 운송물 인도일 또는 인도할 날부터 1년 이내에 재판상 청구가 없으면 소멸한다. 당사자 합의로 연장할 수 있다.","src":"상법 제814조제1항"}]},{"머리":"해상화물운송장(Sea Waybill)","줄":[{"t":"비유통성 기명식 서류. 운송장과 상환으로 인도한다는 문언이 없고, 운송장 제시 없이도 운송인이 수화인에게 인도 가능. 운송 중 양도로 전매하지 못한다.","src":"기출 2021-29"},{"t":"송화인은 수화인이 인도를 청구할 때까지 수화인을 자유롭게 변경할 수 있다. 운송계약의 추정적 증거서류.","src":"기출 2021-29"},{"t":"상법: 운송인은 용선자 또는 송하인의 청구가 있으면 선하증권 대신 해상화물운송장을 발행할 수 있다(전자식 발행 가능). 해상화물운송장임을 표시하고 제853조제1항 각 호 사항을 기재, 운송인이 기명날인 또는 서명한다.","src":"상법 제863조"},{"t":"해상화물운송장이 발행된 경우 운송인이 기재된 대로 운송물을 수령 또는 선적한 것으로 추정한다. 수령인이 기재된 수하인 또는 그 대리인이라고 믿을 만한 정당한 사유가 있으면 권리자가 아니어도 운송인은 책임을 면한다.","src":"상법 제864조"},{"t":"CMI 해상화물운송장 통일규칙(1990): 'carrier'와 'shipper'는 운송계약에 지명된 당사자, 'consignee'는 운송계약에 지명되거나 Rule 6에 따라 대체된 당사자. 'master'가 아니다.","src":"기출 2023-29"},{"t":"AWB는 비유통성 기명식 화물수취증. 선화증권은 유가증권(유통성, 지시식 또는 무기명식). 작성 주체: AWB는 송화인, B/L은 운송인.","src":"기출 2022-27"}]}],"함정":[{"x":"해상화물운송장은 운송 중에 양도를 통해 화물의 전매가 가능하다.","o":"해상화물운송장은 비유통성이라 운송 중 양도로 전매할 수 없다.","src":"기출 2021-29"},{"x":"Received B/L은 화물이 특정 선박에 적재되었음을 명시한 B/L로, ‘on board B/L’이라고도 한다.","o":"On board(Shipped) B/L이 화물이 특정 선박에 적재되었음을 명시한 B/L이다. Received B/L은 선적 전 수취 시점에 발행된다.","src":"기출 2026-23"}]},"#9":{"묶음":[{"머리":"해상운송 4대 조약 개요","줄":[{"t":"해상운송 관련 국제조약: Hague Rules(1924), Hague-Visby Rules(1968), Hamburg Rules(1978), Rotterdam Rules(2008).","src":"기출 2023-11 | 기출 2025-19"},{"t":"항공(Warsaw 1929, Hague Protocol 1955, Montreal 1999), 도로(CMR 1956), 철도(CIM 1970)는 해상조약이 아니다.","src":"기출 2023-11 | 기출 2025-19"},{"t":"UNCTAD Liner Code(1974)는 정기선 해운동맹 관련 행동규범, York-Antwerp Rules는 공동해손 정산 규칙이다. 해상물품운송 책임 조약과 구별.","src":"기출 2025-19 | 기출 2021-38 | 보충"},{"t":"Hague Protocol(1955)은 항공(바르샤바 협약 개정 의정서)이지 해상조약이 아니다. Hague-Visby는 해상.","src":"기출 2025-19"}]},{"머리":"운송인 책임한도","줄":[{"t":"Hague Rules(1924): 포장당 또는 선적단위당 100파운드 또는 동일 금액의 타국통화.","src":"기출 2024-12"},{"t":"Hague-Visby Rules(1968): 포장당·선적단위당 666.67 SDR 또는 kg당 2 SDR 중 높은 금액.","src":"기출 2024-12"},{"t":"Hamburg Rules(1978): 포장당·선적단위당 835 SDR 또는 kg당 2.5 SDR 중 높은 금액.","src":"기출 2024-12"},{"t":"Rotterdam Rules(2008): 포장당·선적단위당 875 SDR 또는 kg당 3 SDR 중 높은 금액. (kg당 4 SDR이 아니다)","src":"기출 2024-12"},{"t":"우리나라 상법: 포장당·선적단위당 666.67 SDR 또는 kg당 2 SDR 중 높은 금액. 운송인 자신의 고의 또는 무모한 작위·부작위로 인한 손해에는 책임제한 불가.","src":"기출 2024-12 | 상법 제797조제1항"},{"t":"컨테이너 운송용기를 쓰는 경우 포장 수는 B/L 등에 기재된 내장 포장·선적단위 수. 기재하지 않으면 컨테이너 전부가 하나의 포장 또는 선적단위. 운송인이 아닌 자가 공급한 컨테이너 자체가 멸실·훼손되면 별개의 포장단위.","src":"상법 제797조제2항"},{"t":"송하인이 운송물의 종류와 가액을 고지하고 선하증권 등에 기재했으면 책임제한 규정을 적용하지 않는다. 고의로 현저하게 부실 고지하면 운송인은 책임을 면한다.","src":"상법 제797조제3항"},{"t":"운송인의 책임경감 특약은 효력이 없다(산 동물 운송, 갑판적 취지를 표면에 기재한 갑판적 운송은 예외).","src":"상법 제799조"},{"t":"운송인의 사용인·대리인도 운송인이 주장할 수 있는 항변과 책임제한을 원용할 수 있다(고의·무모한 작위 제외).","src":"상법 제798조제2항"}]},{"머리":"청구·통지·제소기간","줄":[{"t":"Hamburg Rules: 인도 지연으로 인한 손해배상은 수하인(consignee)에게 물품이 인도된 날 후 60 연속일 이내에 운송인에게 서면통지가 없으면 지급되지 않는다.","src":"기출 2022-13"},{"t":"Hamburg Rules: 운송에 관한 소송은 재판상 또는 중재 절차를 2년 이내에 개시하지 않으면 시효로 소멸(time-barred).","src":"기출 2022-13"},{"t":"Hague / Hague-Visby: 제소기간 1년(인도일 또는 인도할 날부터). Rotterdam Rules: 2년.","src":"보충"},{"t":"상법: 운송인의 송하인·수하인에 대한 채권·채무는 운송물 인도일 또는 인도할 날부터 1년 이내에 재판상 청구가 없으면 소멸. 당사자 합의로 연장 가능.","src":"상법 제814조제1항"},{"t":"상법: 운송인이 인수한 운송을 제3자에게 위탁한 경우, 송하인·수하인이 1년 이내에 운송인과 배상합의를 하거나 재판상 청구를 했으면 그로부터 3개월이 경과하기 전에는 제3자에 대한 운송인의 채권·채무가 소멸하지 않는다.","src":"상법 제814조제2항"}]},{"머리":"Rotterdam Rules(2008) 용어","줄":[{"t":"Volume contract: 합의된 기간 동안 일련의 선적(a series of shipments)으로 특정 수량의 물품을 운송하기로 하는 운송계약.","src":"기출 2026-13"},{"t":"Rotterdam Rules에는 Contract of carriage, Carrier, Non-liner transportation, Liner transportation 등의 정의가 함께 있다.","src":"기출 2026-13"},{"t":"Rotterdam Rules(2008)는 해상구간을 포함하는 door-to-door 운송에 적용하는 점이 특징이다.","src":"보충"}]},{"머리":"조약별 책임 원칙·적용 범위","줄":[{"t":"Hague Rules(1924): 운송인은 항해 개시 전후 상당한 주의로 감항능력을 갖출 의무(감항능력주의의무). 항해상 과실·선박 화재 등 열거 면책. 책임기간은 선적부터 양하까지(tackle to tackle). 선하증권이 발행되는 운송에 적용, 갑판적·산 동물은 제외.","src":"보충"},{"t":"Hague-Visby Rules(1968): Hague Rules를 개정. 책임한도를 포장당·kg당 이중 기준으로 하고(후에 SDR 의정서로 SDR 환산), 제소기간 1년을 규정. 컨테이너 포장 수 계산 규정 추가.","src":"보충"},{"t":"Hamburg Rules(1978): 추정과실 책임, 항해상 과실 면책 폐지. 갑판적·산 동물 운송도 적용. 지연 인도 책임을 인정하고 책임기간을 운송인이 화물을 관리하는 기간 전체(port to port)로 확대. 제소기간 2년.","src":"보충 | 기출 2022-13"},{"t":"Rotterdam Rules(2008): 해상구간을 포함하는 door-to-door 운송에 적용. 항해상 과실 면책 폐지. 한도 875 SDR 또는 3 SDR/kg. Volume contract 정의 도입. 제소기간 2년.","src":"보충 | 기출 2024-12 | 기출 2026-13"},{"t":"Hague-Visby·Hamburg·Rotterdam의 책임한도는 높아지는 순서: 666.67 SDR/2 SDR → 835 SDR/2.5 SDR → 875 SDR/3 SDR.","src":"기출 2024-12"}]}],"함정":[]},"#10":{"묶음":[{"머리":"항공화물운송의 특성","줄":[{"t":"신속성을 바탕으로 정시 서비스가 가능하다. 대부분 야간에 운송이 집중된다(주간 아님).","src":"기출 2023-4 | 기출 2021-18"},{"t":"여객에 비해 계절에 따른 운송수요의 탄력성이 작다.","src":"기출 2023-4"},{"t":"화물추적, 특수화물의 안정성, 보험·클레임 서비스가 우수하다.","src":"기출 2023-4"},{"t":"적하(탑재·하역)를 위해 숙련된 지상작업(지상조업)이 필요하다.","src":"기출 2023-4 | 기출 2021-18"},{"t":"신문·잡지·정기간행물처럼 판매시기가 한정된 품목도 주요 대상이다.","src":"기출 2021-18"},{"t":"항공화물 의뢰는 대부분 항공화물운송주선인(Air Freight Forwarder)을 통해 이루어진다.","src":"기출 2021-20"},{"t":"국제항공화물은 방향별 물동량 불균형이 커 편도운송 경향이 있다.","src":"보충 | 기출 2021-18"},{"t":"AWB는 비유통성 화물수취증이다. 운송 중 매각을 위한 유통성 권리증권이 아니다.","src":"기출 2021-18 | 기출 2022-27"},{"t":"국제전자상거래 성장으로 GDC(Global Distribution Center) 관련 항공화물이 증가한다. 신선화물이 늘고 인천공항의 환적화물 비중이 증가한다.","src":"기출 2021-20"},{"t":"항공화물 단위탑재(ULD): 컨테이너와 파렛트를 쓴다. 이글루(Igloo)도 단위탑재 용기. 고급의류는 컨테이너, 기계부품은 파렛트에 적재하는 것이 적합. 여객기 벨리카고는 파렛트 외 컨테이너·벌크 탑재도 가능.","src":"기출 2021-19"}]},{"머리":"국제항공기구","줄":[{"t":"ICAO(국제민간항공기구, 1947): 1944년 시카고 회의(Chicago Conference, 시카고협약)를 기초로 한 UN 산하 전문기관(정부 간 국제협력기구). 국제민간항공의 안전 확보, 항공시설·기술 발전을 목적으로 한다. 군용항공기는 대상이 아니다.","src":"기출 2023-3 | 기출 2021-22"},{"t":"ICAO 업무: 항공기 사고 조사·방지, 국제항공운송의 간편화, 국제항공법회의에서 초안한 국제항공법 의결.","src":"기출 2023-3"},{"t":"ICAO 회원은 국가이고, 항공사 대표가 참석하는 단체가 아니다.","src":"기출 2023-3"},{"t":"IATA(국제항공운송협회, 1945): 국제정기항공사가 중심인 민간(비정부) 단체. 각국 항공사 대표가 참석하며 ICAO의 협력기구.","src":"기출 2021-22 | 기출 2025-6"},{"t":"IATA 업무: 항공권 약관·규격·발권절차의 통일, 항공사 간 과당경쟁 방지를 위한 운임협정·서비스 내용, 항공운송장의 표준서식·약관 제정.","src":"기출 2025-6"},{"t":"FAI(국제항공연맹, 1905)는 IATA(1945)·ICAO(1947)와 함께 대표적 국제항공기구로 꼽힌다.","src":"기출 2021-22"}]},{"머리":"항공운송 관련 국제조약","줄":[{"t":"항공운송 조약: Warsaw Convention(1929), Hague Protocol(1955), Guadalajara Convention(1961), Montreal Agreement(1966), Guatemala Protocol(1971), Montreal Convention(1999).","src":"기출 2022-20 | 기출 2023-5 | 기출 2024-19 | 보충"},{"t":"Warsaw 조약(1929)은 항공기에 의해 유상으로 행하는 승객·수하물·화물의 국제운송에 적용된다(국내운송 제외). 무상 운송은 항공운송사업자가 행하는 경우에 한한다.","src":"기출 2021-22 | 보충"},{"t":"Montreal Convention(1999): 항공운송 관련 국제협정을 통합하려고 ICAO 국제항공법회의에서 채택, 2003년 발효.","src":"기출 2023-5"},{"t":"항공 조약이 아닌 것: Hague Rules(1924)·Hamburg Rules·Rotterdam Rules(해상), CMR(1956, 도로), CIM(1970, 철도), CMI Uniform Rules for Electronic B/L(1990).","src":"기출 2022-20 | 기출 2024-19 | 기출 2021-22"},{"t":"항공운송 관련 국제규범으로 Guatemala Protocol과 Montreal Agreement가 있다. CIM·CMR은 철도·도로 조약.","src":"기출 2024-19"},{"t":"Montreal Convention(1999) 청구기간: 손상(damage)은 발견 즉시 운송인에게 항의해야 하고 늦어도 수령일부터 수하물 7일, 화물 14일 이내. 지연(delay)은 수하물·화물을 처분 가능하게 한 날부터 21일 이내에 항의.","src":"기출 2026-16"},{"t":"Montreal Convention(1999)의 소송 제기기간은 2년, 화물 책임한도는 SDR로 표시되며 ICAO 주기 개정으로 인상된다(현행 금액 미확인).","src":"보충"},{"t":"국제복합운송에서 항공사가 Through 운송장을 발행하면 항공구간은 바르샤바·몬트리올 체제로 책임을 진다. 함부르크 규칙(해상조약)에 따르지 않는다.","src":"기출 2024-22 | 보충"}]}],"함정":[{"x":"국내항공화물운송과 달리 국제항공화물운송은 대부분 왕복운송형태를 보이고 있다.","o":"국제항공화물은 방향별 물동량 불균형이 커 편도운송 경향을 보인다(출제 기준).","src":"기출 2021-18 | 보충"},{"x":"국제항공화물운송은 송화인이 의뢰한 화물을 그대로 벌크형태로 탑재하기 때문에 지상조업이 거의 필요하지 않다.","o":"항공화물은 단위탑재(ULD) 작업 등 숙련된 지상조업이 필요하다.","src":"기출 2021-18"},{"x":"항공화물운송은 주간운송에 집중되는 경향이 있다.","o":"항공화물운송은 야간운송에 집중되는 경향이 있다.","src":"기출 2021-18"},{"x":"해상화물운송과 달리 항공화물운송은 운송 중 매각을 위해 유통성 권리증권인 항공화물운송장(Air Waybill)이 널리 활용되고 있다.","o":"항공화물운송장(AWB)은 비유통성 화물수취증이라 운송 중 매각에 쓰이는 유통성 권리증권이 아니다.","src":"기출 2021-18"},{"x":"코로나19 등으로 인해 항공화물운송료가 급등하고 있어 전체 물동량은 줄어들고 있다.","o":"출제 오답(운임 급등과 물동량 감소를 연결한 서술이 틀림. 바른 수치 미확인)","src":"기출 2021-20"},{"x":"국제항공운송에 관한 대표적인 조약으로는 Hague규칙(1924), Montreal조약 (1999) 등이 있다.","o":"Hague규칙(1924)은 해상운송 조약이다. 항공운송 조약은 Warsaw조약(1929), Montreal조약(1999) 등이다.","src":"기출 2021-22"},{"x":"ICAO(1947)는 국제정기항공사가 중심이 된 민간단체이지만, IATA(1945)는 정부 간 국제협력기구이다.","o":"ICAO(1947)는 정부 간 국제협력기구(UN 전문기관)이고, IATA(1945)는 국제정기항공사가 중심인 민간단체이다.","src":"기출 2021-22"},{"x":"Warsaw조약(1929)은 항공기에 의해 유무상으로 행하는 수화물 또는 화물의 모든 국내외운송에 적용된다.","o":"Warsaw조약(1929)은 항공기에 의한 국제운송에 적용된다. 국내운송에는 적용되지 않는다.","src":"기출 2021-22"},{"x":"ICAO(1947)의 설립목적은 전 세계의 국내외 민간 및 군용항공기의 안전과 발전을 도모하는데 있다.","o":"ICAO(1947)의 설립목적은 국제민간항공의 안전과 발전이다. 군용항공기는 대상이 아니다.","src":"기출 2021-22"},{"x":"회원국의 항공사 대표들이 참석하는 국제연합(UN) 산하의 전문기관이다.","o":"ICAO는 회원국 정부 대표가 참여하는 UN 산하 전문기관이다. 항공사 대표가 참석하는 단체는 IATA이다.","src":"기출 2023-3"},{"x":"여객에 비해 계절에 따른 운송수요의 탄력성이 크다.","o":"항공화물은 여객에 비해 계절에 따른 수요의 탄력성이 작다.","src":"기출 2023-4"},{"x":"정부 간 국제협력기구로서 UN 산하의 전문기관이다.","o":"IATA는 항공사 중심의 민간(비정부) 국제단체이다. UN 산하 전문기관은 ICAO이다.","src":"기출 2025-6"}]},"#11":{"묶음":[{"머리":"AWB의 기능과 발행","줄":[{"t":"AWB는 비유통성·기명식 화물수취증이다. 기재된 수화인이 아니면 화물을 인수할 수 없다.","src":"기출 2025-27 | 기출 2022-27"},{"t":"AWB 기능: 화물수령증, 운송계약 체결의 증거, 요금계산서, 세관신고서(수출입신고 및 통관자료), 보험 관련 서류.","src":"기출 2021-26 | 기출 2024-24"},{"t":"AWB는 송화인(또는 그 대리인)이 작성한다. 항공사 또는 항공사 대리점이 작성하는 것이 아니다.","src":"기출 2022-16 | 기출 2022-27 | 기출 2025-27"},{"t":"송화인은 AWB에 기재된 화물의 명세·신고의 정확성에 대해 AWB를 누가 작성했든 책임을 진다.","src":"기출 2022-16"},{"t":"원본 3통을 1조로 작성해 화물과 함께 운송인에게 교부한다. 원본 1(녹색)은 운송인용(송화인 서명), 원본 2(적색)는 수화인용(송화인·운송인 서명, 화물과 함께 도착지 송부), 원본 3(청색)은 송화인용(운송인이 서명하고 화물 인수 후 송화인에게 교부).","src":"기출 2022-16 | 기출 2021-26"},{"t":"원본 3은 화물수취증 기능. 사본 4는 수화인의 화물수령 증거(배달영수증).","src":"기출 2021-26"},{"t":"AWB는 원본 3통과 여러 통의 부본으로 구성되고, 필요하면 추가 부본을 발행할 수 있다.","src":"기출 2025-27 | 보충"},{"t":"Master AWB: 항공사가 항공화물운송주선업자(포워더)에게 발행. House AWB: 포워더가 혼재화물의 개별 화주에게 발행.","src":"기출 2025-27"},{"t":"AWB 신용장 요건: 원본 전통을 요구하더라도 송화인용 원본이 제시되어야 한다.","src":"기출 2023-26 | 기출 2026-30"}]},{"머리":"AWB 기재란","줄":[{"t":"Currency: AWB 발행국 화폐단위 코드. Currency란에 나타난 모든 금액은 AWB에 표시되는 화폐단위와 일치.","src":"기출 2024-16 | 기출 2025-7"},{"t":"Declared Value for Carriage: 송화인이 신고하는 운송신고가격. 신고할 가격이 없으면 NVD(No Value Declared).","src":"기출 2024-16 | 기출 2025-7 | 기출 2026-18"},{"t":"Declared Value for Customs: 송화인의 세관신고가격. 없으면 NCV(No Customs Value).","src":"기출 2025-7 | 보충"},{"t":"Amount of Insurance: 화주가 보험에 부보하는 보험금액. 부보하지 않으면 공백.","src":"기출 2024-16 | 기출 2025-7"},{"t":"Consignment Details and Rating: 화물요금 관련 세부사항.","src":"기출 2024-16"},{"t":"Chargeable Weight: 실제중량과 부피중량 중 높은 쪽 중량. 최저운임이 적용되면 기재할 필요 없다.","src":"기출 2024-16 | 기출 2025-7"}]},{"머리":"항공운임","줄":[{"t":"품목분류요율(CCR)의 할증 적용 품목: 금괴, 화폐, 유가증권, 생동물, 시체 등. 잡지(신문·잡지·정기간행물)와 화물로 운송되는 개인의류·개인용품은 할인 품목.","src":"기출 2022-14 | 기출 2026-14 | 보충"},{"t":"BUC(Bulk Unitization Charge, 단위탑재용기 요금): 컨테이너·파렛트 단위로 부과. 실제 중량이 Pivot weight를 넘으면 Pivot charge + (초과 중량 × Over pivot charge).","src":"기출 2025-8"},{"t":"BUC 계산 예: Pivot weight 2,400kg, Pivot charge US$9,000, Over pivot US$4.00/kg, 실제 2,500kg → 9,000 + 100×4 = US$9,400.","src":"기출 2025-8"},{"t":"BUC 사용제한 품목: 유해물, 귀중화물, 위험물품, 살아있는 동물. 중량화물은 제한 품목이 아니다.","src":"기출 2023-7"},{"t":"Disbursement fee(대불비용 수수료): 송하인 또는 대리인이 선지급한 비용으로 수하인이 부담하는 육상운송료·보관료·통관수수료 등. 운송인이 송하인 요구에 따라 AWB를 통해 수하인에게 징수.","src":"기출 2024-17 | 기출 2026-15"},{"t":"Charges collect fee: 수하인이 운임을 납부하도록 된 항공화물에 대해 그 금액의 일정 비율을 항공사가 징수하는 수수료.","src":"기출 2026-15"},{"t":"Pick up service charge, Documentation fee, Dangerous goods handling fee/charge, Handling charge는 다른 부대운임.","src":"기출 2024-17 | 기출 2026-15"}]},{"머리":"항공화물 사고 유형","줄":[{"t":"손상(damage) 유형: Breakage(파손), Wet(젖음), Spoilage, Mortality(생동물 폐사).","src":"기출 2022-15"},{"t":"Shortlanded(STLD): 적하목록에는 기재되어 있으나 도착지 공항에 화물이 도착하지 않은 경우.","src":"기출 2025-5"},{"t":"Miss-labelled(MSLB): 실제 적하목록에 기재된 AWB 번호와 다른 라벨이 붙은 경우. Cross Labelled는 라벨이 바뀌거나 운송장번호·목적지 등을 잘못 기재한 경우.","src":"기출 2025-5 | 기출 2024-11"},{"t":"Off-Load(OFLD): 출발지나 경유지에서 탑재공간 부족·항공기 안전 확보·업무 착오로 의도적이거나 실수로 화물을 내린 경우.","src":"기출 2024-11 | 기출 2025-5"},{"t":"Over-Carried(OVCD): 화물이 하기되어야 할 지점을 지나서 내려진 경우.","src":"기출 2024-11"},{"t":"Short-Shipped(SSPD): 적재화물목록에는 기재되어 있으나 화물이 탑재되지 않은 경우. (수화인 수취 거절과는 다르다)","src":"기출 2024-11 | 기출 2025-5"},{"t":"Miss-connected(MSCN): 연결편 환승 과정에서 다음 항공편에 탑재되지 못한 경우로 지연 유형이다. 탑재·하기·인수·타 항공사 인계 시의 '분실'과는 다르다.","src":"기출 2024-11 | 보충"}]},{"머리":"위험물(IATA DGR)","줄":[{"t":"위험화물: 항공운송 중 기압·온도 변화, 기체 흔들림 등으로 항공기·인명·인접화물에 피해를 줄 우려가 있는 화물.","src":"기출 2025-9"},{"t":"IATA 위험물 취급규정(DGR)에 수송 여부와 제한사항이 규정되어 있다. 위험품목은 9개 부류(Class 1~9)이며 송화인의 책임을 규정한다.","src":"기출 2025-9"},{"t":"송화인은 DGR 절차에 따라 분류·인식·포장·마킹·라벨링을 하고 서류를 작성한다. 화주신고서(Shipper's Declaration for Dangerous Goods) 작성·서명도 송화인이 한다.","src":"기출 2025-9"},{"t":"독성물질은 Class 6(독물 및 감염성 물질). Class 1 폭발물, 2 가스, 3 인화성 액체, 4 인화성 고체 등, 5 산화성 물질·유기과산화물, 7 방사성 물질, 8 부식성 물질, 9 기타 위험물.","src":"기출 2026-17 | 보충"}]}],"함정":[{"x":"여객기에 탑재하는 벨리카고(Belly Cargo)는 파렛트를 활용한 단위탑재만 가능하다.","o":"여객기 벨리카고는 파렛트뿐 아니라 컨테이너 등 다른 탑재 형태도 가능하다.","src":"기출 2021-19"},{"x":"항공화물운송장 원본 2는 적색으로 발행되며, 송화인용이다.","o":"원본 1(녹색)은 운송인용, 원본 2(적색)는 수화인용, 원본 3(청색)은 송화인용이다.","src":"기출 2021-26"},{"x":"송화인은 항공화물운송장에 기재된 화물의 명세ㆍ신고가 정확하다는 것에 대해 그 항공화물운송장을 누가 작성했든 책임을 질 필요가 없다.","o":"송화인은 AWB에 기재된 화물의 명세·신고의 정확성에 대해 AWB를 누가 작성했든 책임을 진다.","src":"기출 2022-16"},{"x":"항공운송서류는 항공화물운송장(AWB)의 명칭과 발행일이 표시되어야 한다.","o":"항공운송서류는 명칭과 관계없이 요건을 충족하면 수리되며, 발행일이 표시되어야 한다(UCP 600 제23조).","src":"기출 2023-26 | 보충"},{"x":"Declared Value for Carriage란은 항공사의 운송신고가격을 기입한다.","o":"Declared Value for Carriage란에는 송화인(shipper)이 신고한 운송신고가격을 기재한다.","src":"기출 2024-16"},{"x":"Declared Value for Carriage란은 송화인의 운송신고가격을 기재하며, 무가격 신고는 NCV라고 기재한다.","o":"운송신고가격이 없으면 NVD(No Value Declared), 세관신고가격이 없으면 NCV(No Customs Value)로 기재한다.","src":"기출 2025-7"},{"x":"화주신고서(shipper's declaration for dangerous goods)에 대한 작성 및 서명은 항공사가 한다.","o":"화주신고서(Shipper's Declaration for Dangerous Goods)의 작성·서명은 송화인이 한다.","src":"기출 2025-9"},{"x":"House AWB는 항공사가 혼재화물에 대하여 발행하는 항공화물운송장이다.","o":"House AWB는 항공화물운송주선업자(포워더)가 혼재화물의 개별 화주에게 발행한다.","src":"기출 2025-27"},{"x":"원본 3통, 부본 6통으로 발행하는 것이 원칙이며, 추가 부본을 발행할 수 없다.","o":"AWB는 원본 3통과 여러 통의 부본으로 구성되며, 필요하면 추가 부본을 발행할 수 있다(출제 부본 수·추가 불가 서술이 오답).","src":"기출 2025-27"},{"x":"Master AWB는 항공화물 운송주선업자가 혼재화물을 구성하는 개별 화주에게 발행하는 운송장이다.","o":"Master AWB는 항공사가 항공화물운송주선업자에게 발행하는 운송장이다.","src":"기출 2025-27"},{"x":"항공화물운송장은 항공사나 항공사의 위임을 받은 대리점이 작성한다.","o":"AWB는 송화인(또는 그 대리인)이 작성한다.","src":"기출 2025-27"},{"x":"신용장이 원본 전통(full set)을 요구하더라도 수하인용 원본으로 보여야 한다.","o":"신용장이 원본 전통을 요구하더라도 송화인용 원본으로 보여야 한다.","src":"기출 2026-30"}]},"#12":{"묶음":[{"머리":"컨테이너 규격·재질·용도","줄":[{"t":"크기: ISO 규격 20 feet, 40 feet, 40 feet High Cubic.","src":"기출 2022-23"},{"t":"재질: 철재·알루미늄·강화플라스틱(FRP). 철재컨테이너는 강하고 저렴하나 무겁고 녹이 슨다. 알루미늄컨테이너는 가볍고 녹슬지 않으나 제조원가가 높다.","src":"기출 2022-23 | 보충"},{"t":"용도: 표준컨테이너, 온도조절컨테이너, 특수컨테이너.","src":"기출 2022-23"},{"t":"Dry Container: 일반 건화물용 표준 컨테이너.","src":"기출 2022-22 | 기출 2023-22"},{"t":"Reefer(냉동) Container: 과일·야채·생선·육류 등 보냉이 필요한 화물.","src":"기출 2022-23"},{"t":"Open Top Container: 기계류·철강제품·판유리 등 중량화물·장척화물을 크레인으로 위쪽에서 적재·하역. 천장은 캔버스 덮개(방수).","src":"기출 2023-22"},{"t":"Flat Rack Container: 드라이 컨테이너의 천장과 측벽을 제거한 형태로 바닥과 네 기둥만 남음. 기계류·전신주·원목 등 중량물을 전후좌우 또는 상방에서 지게차로 하역.","src":"기출 2026-26"},{"t":"Tank(Liquid Bulk) Container: 위험물·석유화학제품·화공약품·유류·술 등 액체화물. 내부에 원통형 탱크를 위치시키고 외부를 철재 프레임으로 고정.","src":"기출 2022-22 | 기출 2021-16"},{"t":"Solid Bulk Container: 곡물·분체 등 건화물 벌크. Hanger(Garment) Container: 정장·실크·밍크 등 고급의류를 옷걸이에 걸어 구김 없이 운송, 다림질 없이 진열·판매. Ventilated Container: 통풍. Insulated Container: 단열.","src":"기출 2024-21 | 기출 2026-26 | 보충"},{"t":"컨테이너화물은 하역을 LO-LO 방식뿐 아니라 RO-RO 방식으로도 할 수 있다.","src":"기출 2021-16"}]},{"머리":"FCL/LCL과 인도 형태","줄":[{"t":"FCL(Full Container Load)과 LCL(Less than Container Load): 컨테이너 1개 만재 여부로 구분.","src":"기출 2021-21"},{"t":"CY→CY(FCL→FCL): 수출지 CY에서 수입지 CY까지 FCL로 운송. 컨테이너 장점을 최대로 살리는 방식, Door-to-Door 서비스 가능. 실무에서 가장 많이 이용.","src":"기출 2021-21 | 기출 2023-24 | 기출 2025-16"},{"t":"CFS→CFS(LCL→LCL): 수출지 CFS에서 수입지 CFS까지. 운송인이 다수 송화인의 LCL화물을 모아 혼재하여 운송(다수 송화인-다수 수화인).","src":"기출 2021-21 | 기출 2025-16"},{"t":"CFS→CY(LCL→FCL): 운송인이 다수 송화인의 화물을 모아 수출지 CFS에서 혼재해 FCL로 만들고, 수입지 CY에서 분류 없이 수화인에게 인도. 단일 수입상이 다수 수출상으로부터 수입할 때 이용. 다수 송하인-한 명의 수하인.","src":"기출 2021-21 | 기출 2025-16 | 기출 2026-27"},{"t":"CY→CFS(FCL→LCL): 수출지 CY에서 수입지 CFS까지. 한 송화인-다수 수화인 구조. 수입지 CFS에서 분류해 각 수입업자에게 인도.","src":"기출 2021-21 | 기출 2022-28 | 기출 2023-24"},{"t":"CY(Container Yard): 컨테이너를 인수·인도·보관하는 장소로 Apron, CFS 등을 포함.","src":"기출 2023-24"}]},{"머리":"컨테이너화의 이점·단점","줄":[{"t":"이점: 화물취급 편리, 운송 신속, 운송비·하역비·인건비 절감, 하역 기계화, 해륙일관운송과 환적시간 단축, 송화인 문전~수화인 문전 Door-to-Door 서비스, 신속·안전한 환적.","src":"기출 2022-28 | 기출 2023-24 | 기출 2024-23 | 기출 2026-27"},{"t":"단점: 컨테이너 유휴 등 고가 설비의 효율적 활용이 쉽지 않음, 소량화물은 혼재 불편, 모든 화물을 컨테이너화할 수 없음, 선사직원·항만노무자 교육·훈련에 장기간 노력과 투자 필요.","src":"기출 2024-23"},{"t":"현대적 컨테이너 운송의 시초: 1956년 미국 해상운송(Sea-Land).","src":"보충 | 기출 2021-16"}]},{"머리":"FCL 선적절차와 서류","줄":[{"t":"FCL 선적 순서: 공컨테이너 반입요청 및 반입 → 공컨테이너에 화물 적입 및 CLP 작성 → Pick-up 요청과 내륙운송 및 CY 반입 → D/R(부두수취증)과 CLP 제출 → B/L 수령 및 수출대금 회수.","src":"기출 2021-23"},{"t":"D/R(Dock Receipt, 부두수취증): 컨테이너 운항 선사가 화주로부터 화물을 수취했을 때의 수령증으로 화물 상태를 증명.","src":"기출 2026-27"},{"t":"CLP(Container Load Plan): 컨테이너 내부의 화물 적부도. 본선 내 컨테이너 적재 위치도는 Stowage(Bay) plan.","src":"기출 2026-27 | 보충"}]},{"머리":"컨테이너 관련 국제협약","줄":[{"t":"CCC(Customs Convention on Container, 1956): 컨테이너 관세협약.","src":"기출 2022-30 | 기출 2023-23 | 기출 2025-10"},{"t":"TIR(Transport International Routiere, 1959): 유럽경제위원회 채택. 도로 주행차량으로 운송되는 봉인 컨테이너 내 화물은 경유지 세관에서 수출입세 납부·공탁 면제, 원칙적으로 세관검사 면제.","src":"기출 2025-10"},{"t":"ITI(Customs Convention on the International Transit of Goods, 1971): 물품의 국제통과에 관한 관세협약.","src":"기출 2022-30 | 기출 2023-23"},{"t":"CSC(International Convention for Safe Containers, 1972): 컨테이너의 구조상 안전요건을 국제적으로 통일하기 위해 UN과 IMO가 공동 채택.","src":"기출 2023-23 | 기출 2022-30"},{"t":"YAR(York-Antwerp Rules)은 공동해손 규칙이고 컨테이너 협약이 아니다. MIA(Marine Insurance Act, 1906)는 영국 해상보험법. CMR(1956)은 도로운송 계약 협약.","src":"기출 2022-30 | 기출 2023-23 | 기출 2025-10"},{"t":"함부르크 규칙은 컨테이너의 성격·구조 규정이 아니라 해상물품운송 책임 규칙이다.","src":"기출 2021-16"}]},{"머리":"컨테이너 화물 손해","줄":[{"t":"발생빈도는 낮으나 건당 손해액이 큰 사고: 화재, 갑판유실 등.","src":"기출 2026-19"},{"t":"컨테이너 화물에 생기기 쉬운 손해: 결로 등.","src":"기출 2026-19"},{"t":"발생빈도는 높으나 건당 손해액이 적은 사고: 파손, 곡손, 도난(theft), 발하(拔荷, pilferage), 불착.","src":"기출 2026-19"},{"t":"도난(theft): 화물을 포장째 훔치는 행위. 발하(pilferage): 포장화물의 일부를 꺼내는 행위.","src":"기출 2026-19"}]},{"머리":"TEU 환산","줄":[{"t":"20피트 컨테이너 1개 = 1 TEU, 40피트 컨테이너 1개 = 2 TEU(FEU, Forty-foot Equivalent Unit).","src":"보충"}]}],"함정":[{"x":"컨테이너운송은 1920년대 미국에서 해상화물운송용으로 처음 등장하여 군수물자의 운송에 사용된 것이 시초이다.","o":"출제 오답(바른 연도 미확인). 현대적 컨테이너 운송은 1956년 미국의 해상운송에서 시작되었다.","src":"기출 2021-16 | 보충"},{"x":"컨테이너의 성격과 구조에 관하여는 일반적으로 함부르크 규칙(1978)에서 규정 하고 있다.","o":"컨테이너의 구조상 안전요건은 CSC(1972), 세관 관련은 CCC(1956)·TIR(1959) 등이 규정한다. 함부르크 규칙은 해상물품운송 책임에 관한 규칙이다.","src":"기출 2021-16"},{"x":"특수컨테이너의 지속적인 개발로 컨테이너화물의 운송비중은 현재 전 세계 물동량 의 약 70 %에 달하고 있다.","o":"출제 오답(바른 수치 미확인)","src":"기출 2021-16"},{"x":"컨테이너화물의 하역에는 LO-LO(Lift On/Lift Off) 방식만 적용 가능하다.","o":"컨테이너화물의 하역은 LO-LO 방식뿐 아니라 RO-RO 방식으로도 가능하다.","src":"기출 2021-16"},{"x":"CY → CFS (FCL → LCL)운송: 수출지 CY로부터 수입지 CFS까지 운송하는 방식 으로, 다수의 송화인과 다수의 수화인 구조를 갖고 있다.","o":"CY→CFS(FCL→LCL)는 한 송화인-다수 수화인 구조이다. 다수 송화인-다수 수화인 구조는 CFS→CFS(LCL→LCL)이다.","src":"기출 2021-21"},{"x":"알루미늄컨테이너는 무겁고 녹이 스는 단점이 있으나 제조원가가 저렴하여 많이 이용된다.","o":"무겁고 녹이 스는 단점이 있으나 제조원가가 저렴해 많이 이용되는 것은 철재컨테이너이다. 알루미늄컨테이너는 가볍고 녹슬지 않으나 제조원가가 높다.","src":"기출 2022-23"},{"x":"CY/CFS(FCL/LCL)운송은 수출지 CY로부터 수입지 CFS까지 운송하는 방식으 로 다수의 송화인과 다수의 수화인으로 구성되어져 있다.","o":"CY/CFS(FCL/LCL)운송은 한 송화인-다수 수화인 구조이다.","src":"기출 2022-28"},{"x":"CY/CFS는 선적지에서 수출업자가 LCL화물로 선적하여 목적지 항만의 CFS에서 화물을 분류하여 수입업자에게 인도한다.","o":"CY/CFS는 수출지 CY에서 FCL로 선적하여 수입지 CFS에서 분류한 뒤 다수 수입업자에게 인도하는 방식이다.","src":"기출 2023-24"},{"x":"컨테이너화에는 선사직원 및 항만노무자의 교육·훈련 등에 있어 장기간의 노력과 투자가 필요하지 않다.","o":"컨테이너화에는 선사직원·항만노무자의 교육·훈련 등에 장기간의 노력과 투자가 필요하다.","src":"기출 2024-23"},{"x":"CY/CFS는 실무에서 가장 많이 이용되는 방식이다.","o":"실무에서 가장 많이 이용되는 방식은 CY/CY이다.","src":"기출 2025-16"},{"x":"컨테이너 내부 적부도(Container load plan)는 본선 내의 컨테이너 적재 위치를 나타내는 일종의 위치도이다.","o":"CLP는 컨테이너 내부 화물의 적부도이다. 본선 내 컨테이너 적재 위치도는 Stowage(Bay) plan이다.","src":"기출 2026-27"}]},"#13":{"묶음":[{"머리":"항만 시설","줄":[{"t":"Quay(안벽): 해안에 평행하게 축조된, 선박 접안을 위해 수직으로 만든 옹벽.","src":"기출 2023-28"},{"t":"Apron: 안벽에 접한 하역 작업장. Marshalling Yard: 선적할 컨테이너나 양륙 완료된 컨테이너를 적재·보관하는 장소.","src":"기출 2023-28"},{"t":"묘박지(Anchorage): 선박이 닻을 내리고 접안을 위해 대기하는 수역.","src":"기출 2024-25"},{"t":"계선주(Bitt): 선박의 계선밧줄을 고정하기 위해 안벽에 설치한 석재 또는 강철재의 짧은 기둥.","src":"기출 2024-25"},{"t":"펜더(Fender): 선박 접안 시 또는 접안 중 선박이 접촉하더라도 파손되지 않도록 안벽 외측에 부착한 고무재.","src":"기출 2024-25"},{"t":"선회장(Turning Basin): 자선선회(자력 선회)의 경우 본선 길이의 3배를 직경으로 하는 원, 예선(曳船)이 있으면 2배를 직경으로 하는 원.","src":"보충 | 기출 2024-25"},{"t":"항로(Access Channel): 바람과 파랑의 방향에 대해 30°~60°의 각도, 조류방향과 작은 각도를 이루는 것이 좋다.","src":"기출 2024-25"},{"t":"항만과 공항: Sea&Air 운송 등 상호 보완 기능을 위해 인접 입지가 좋다. 항만에 인접해 물류단지를 조성하는 것이 일반적이고, 공항 주변에도 물류단지를 조성한다. 공항은 Hub&Spokes 형태로 입지·운영. 국제전자상거래업체는 입지와 무관하게 물류센터를 확보하는 것이 아니라 항만·공항 입지를 고려한다.","src":"기출 2021-30"},{"t":"항만·공항 추세: 터미널 대형화, 환적·화물분류·통관·유통가공 등 부가가치 물류활동 장소로 변화, 항공기·선박 대형화로 공항·항만 간 경쟁 치열, 정기선사·항공사와 글로벌 제휴 확대, Hub&Spoke 확대(point-to-point 아님).","src":"기출 2025-26"}]},{"머리":"컨테이너 터미널 하역장비","줄":[{"t":"Gantry Crane: 컨테이너 하역 전용 크레인. Apron에 부설된 레일 위를 이동하며 컨테이너를 본선에 선적·양륙.","src":"기출 2026-28 | 기출 2023-28"},{"t":"Yard Tractor: Apron과 CY 간 컨테이너 이동 장비. 야드 샤시(chassis)와 결합하여 사용. 컨테이너를 트럭에 적재·양륙하는 장비가 아니다.","src":"기출 2023-28 | 기출 2026-28"},{"t":"Straddle Carrier: 양다리 사이에 컨테이너를 끼워 하역과 운반을 동시에 하는 기동성 높은 차량.","src":"기출 2023-28 | 기출 2026-28"},{"t":"Transtainer(Transfer Crane): 컨테이너를 장치하거나 장치된 컨테이너를 Chassis 또는 화차 등에 옮겨 싣는 기중기.","src":"기출 2026-28 | 기출 2022-21"},{"t":"Winch crane: 컨테이너를 Chassis 또는 트럭에 적재·양륙하는 기중기. 좌우 회전 가능, 자력으로 작업장까지 이동 가능.","src":"기출 2026-28"},{"t":"Transfer Crane은 컨테이너터미널(CY) 장비이고 공항터미널 조업장비가 아니다.","src":"기출 2022-21"}]},{"머리":"공항터미널 조업장비","줄":[{"t":"공항 조업장비: High Loader, Transporter, Tug Car, Dolly, Nose Dock, Self-Propelled Conveyor, Work Station 등.","src":"기출 2022-21 | 기출 2024-14"},{"t":"Nose Dock: 주기장에서 항공기와 터미널을 직접 연결해 탑재·하역을 쉽게 한다. Tug Car: 파렛트 트레일러(Dolly)를 연결하여 이동하는 차량.","src":"기출 2024-14"},{"t":"High Loader는 항공기 화물실 높이에 컨테이너·파렛트를 올리고 내리는 승강 장비(보충).","src":"보충 | 기출 2024-14"}]},{"머리":"내륙컨테이너기지(ICD)","줄":[{"t":"ICD는 항만이나 공항이 아닌 내륙에 설치된 컨테이너 운송 관련 시설로 고정설비를 갖춘다.","src":"기출 2021-31 | 기출 2023-31"},{"t":"본래 내륙통관기지(Inland Clearance Depot)를 의미했으나 컨테이너화 확산으로 내륙컨테이너기지(Inland Container Depot)로 성장.","src":"기출 2021-31"},{"t":"ICD 기능: 컨테이너화물의 통관·배송·보관·집화, 컨테이너 적입 및 적출, 장치·보관, 수리, 소량화물의 혼재·분류, 공컨테이너 장치장, 수출입 화주의 유통센터·창고 기능, 화물의 일시적 저장과 취급 서비스, 수출입 통관 및 화물유통기지. 통관절차를 내륙으로 이동한 내륙통관기지.","src":"기출 2021-31 | 기출 2022-39 | 기출 2023-31 | 기출 2025-31 | 기출 2026-31"},{"t":"ICD는 철도와 도로가 연결되는 복합운송거점으로 대량운송을 통해 운송비를 절감하고 항만지역 교통 혼잡을 줄인다.","src":"기출 2021-31 | 기출 2023-31"},{"t":"ICD는 보세구역 성격의 공설기지이며, 세관통제 하의 통관 전 보세화물 일시 장치도 포함한다.","src":"기출 2023-31 | 기출 2026-31"},{"t":"ICD에는 본선 선적 및 양하 기능이 없다. 본선적재·마셜링은 항만의 컨테이너터미널 기능.","src":"기출 2025-31 | 기출 2022-39"},{"t":"ICD는 선사·화주·행정당국 등의 국제물류 전용 정보교환센터로만 활용되는 곳이 아니다.","src":"기출 2026-31"}]}],"함정":[{"x":"내륙의 공항 내에 설치되어 있는 시설로서 운송기지 또는 운송거점으로서의 역할이 강조되고 있다.","o":"ICD는 내륙의 컨테이너 운송 관련 시설이다. 공항 내 시설이 아니다.","src":"기출 2021-31"},{"x":"항만에서 이루어지는 본선적재작업과 마셜링 기능을 수행한다.","o":"ICD는 내륙기지이다. 본선적재작업과 마셜링은 항만 컨테이너터미널의 기능이다.","src":"기출 2022-39"},{"x":"Gantry Crane은 CY에서 컨테이너를 트레일러에 싣고 내리는 작업을 수행하는 장비이다.","o":"Gantry Crane은 Apron의 레일 위를 이동하며 본선의 컨테이너를 선적·양륙하는 장비이다. CY에서 트레일러에 싣고 내리는 작업은 다른 장비(Transtainer·Winch crane 등)가 한다.","src":"기출 2023-28"},{"x":"세관통제하에 통관된 수출입화물만을 대상으로 일시저장과 취급에 대한 서비스를 제공한다.","o":"ICD는 통관 전 보세화물과 통관 후 화물을 모두 일시 저장·취급하는 보세구역 성격의 시설이다.","src":"기출 2023-31"},{"x":"선회장(Turning Basin)은 자선선회(自船船回)의 경우 본선 길이의 2배를 직경으로 하는 원이며, 예선(曳船)이 있을 경우에는 본선 길이의 3배를 직경으로 하는 원으 로 한다.","o":"선회장은 자선선회의 경우 본선 길이의 3배, 예선이 있으면 2배를 직경으로 하는 원이다.","src":"기출 2024-25 | 보충"},{"x":"운송수단의 대형화로 인해 지점-지점(point to point) 전략이 확대되고 있다.","o":"운송수단 대형화로 허브 앤 스포크(Hub&Spoke) 전략이 확대되고 있다.","src":"기출 2025-26"},{"x":"Yard tractor는 컨테이너 화물을 트럭에 적재하거나 또는 트럭에서 양륙할 때 사용하는 차량이다.","o":"Yard tractor는 Apron과 CY 간 컨테이너를 야드 샤시에 실어 이동시키는 견인차량이다. 트럭에 적재·양륙하는 장비는 아니다.","src":"기출 2026-28"},{"x":"보세구역으로 선사, 화주, 행정당국 등 관련자들이 국제물류 전용 정보교환센터 로만 활용된다.","o":"ICD는 컨테이너 적입·적출, 장치·수리, 통관, 화물유통, 공컨테이너 장치 등 복합 기능을 수행하는 시설이다. 정보교환센터로만 쓰이는 곳이 아니다.","src":"기출 2026-31"}]},"#14":{"묶음":[{"머리":"복합운송의 정의·요건","줄":[{"t":"국제복합운송: 하나의 계약으로 운송의 시작부터 종료까지 운송물을 적어도 서로 다른 2가지 이상의 운송수단으로 운송하는 것.","src":"기출 2022-18 | 기출 2023-10 | 기출 2021-24"},{"t":"요건: 단일 운송책임, 단일 운송계약, 단일(일관) 운임(through rate), 이종의 복수 운송수단, 복합운송증권 발행. 단일 운송수단이 아니다.","src":"기출 2025-13 | 기출 2022-18 | 기출 2021-24"},{"t":"1인의 계약운송인이 누가 운송을 실행하느냐와 관계없이 운송 전체에 단일 운송인책임(single carrier's liability)을 진다.","src":"기출 2022-18"},{"t":"컨테이너운송의 발달이 복합운송 발달의 계기. 북미 및 시베리아 횡단철도와 해상운송 연계 경로 개척으로 해륙복합운송 발달.","src":"기출 2021-24 | 기출 2022-18 | 기출 2025-13"},{"t":"컨테이너 복합운송은 재래식 운송에 비해 하역비·포장비·보관비 등에서 경제적 효과가 있다.","src":"기출 2025-13"},{"t":"'국제복합운송'이라는 용어는 1980년 UN 국제복합운송조약(국제물품복합운송에 관한 UN협약)에서 사용되었다. 바르샤바조약(1929)은 항공운송 조약이다.","src":"보충 | 기출 2021-24"},{"t":"Piggy-Back: 화물 트럭이나 트레일러를 철도 화차에 적재하여 운송하는 방식.","src":"기출 2025-13"}]},{"머리":"복합운송인과 복합운송주선인","줄":[{"t":"실제운송인형(Actual carrier) 복합운송인(VOCC): 직접 운송수단을 보유하고 복합운송인의 역할·책임 수행.","src":"기출 2025-11 | 기출 2023-6"},{"t":"계약운송인형(Contracting carrier) 복합운송인: 운송수단을 보유하지 않고 운송주체자로서 역할·책임 수행. NVOCC·포워더형.","src":"기출 2025-11"},{"t":"NVOCC(Non-Vessel Operating Common Carrier): 선박을 직접 소유하지 않고 해상운송인에 대해서는 화주의 입장, 화주에 대해서는 운송인의 입장에서 운송. 미국 신해운법이 포워더형 복합운송인을 법제화한 개념. 자체 Tariff를 갖고 자기 명의로 B/L(House B/L)을 발행한다.","src":"기출 2023-6 | 기출 2025-11 | 기출 2022-18"},{"t":"복합운송주선인: 송화인으로부터 화물을 인수하여 수화인에게 인도할 때까지 적재·운송·보관 등의 업무를 주선. 집화·분류·수배송·혼재작업. 화주를 대신해 보험계약을 체결하기도 한다. 해상화물과 항공화물 모두 주선 가능. 스스로 운송계약의 주체(복합운송인)가 될 수 있다.","src":"기출 2021-17"},{"t":"혼재(consolidation)는 LCL화물 대상이다. 포워더는 화주에게 House B/L을 발행하고, 선사가 포워더에게 Master B/L을 발행한다.","src":"보충 | 기출 2025-13"}]},{"머리":"복합운송증권","줄":[{"t":"기능: 물품수령증, 운송계약 증거, 수령지로부터 최종인도지까지 전 운송구간을 운송인이 인수했음을 증명. 지시식으로 발행되면 배서·교부로 양도 가능.","src":"기출 2022-29"},{"t":"유통성(양도 가능) 또는 비유통성 중 선택하여 발행한다. 유통성만 또는 비유통성만 발행하는 것이 아니다. 비유통성은 지명된 수화인을 기재해야 한다.","src":"기출 2021-28 | 기출 2023-10 | 기출 2022-29 | 기출 2025-30"},{"t":"복합운송인이 화물을 인수한 시점에 발행(본선 적재 전 수취·인수 상태에서 발행)된다. 운송주선인(포워더)도 발행할 수 있다.","src":"기출 2021-28 | 기출 2025-30"},{"t":"책임기간: 화물을 인수한 때부터 인도할 때까지. 선적~양륙이 아니다.","src":"기출 2021-28 | 기출 2024-20"},{"t":"FIATA FBL은 널리 사용되며 유통성 양식이 대부분이다.","src":"기출 2025-30"},{"t":"UN 국제복합운송조약은 복합운송인이 인수 시 복합운송증권을 발행하게 하고, 유통성/비유통성은 송하인 선택.","src":"기출 2023-10 | 보충"}]},{"머리":"복합운송인 책임체계","줄":[{"t":"단일책임체계(uniform liability system): 사고발생 구간에 관계없이 동일한 기준·한도로 책임.","src":"기출 2023-8 | 기출 2022-19"},{"t":"이종(네트워크)책임체계(network liability system): 손해발생구간이 판명된 경우 그 구간에 적용될 국제조약·강행적 국내법에 따라 책임을 결정. 불명이면 별도 체계. 기존 운송조약과 조화가 좋아 규칙 간 충돌을 방지.","src":"기출 2022-19 | 기출 2023-8"},{"t":"절충식(변형단일, modified uniform) 책임체계: 단일책임체계와 이종책임체계의 절충. UN 국제복합운송조약(1980)이 채택. UNCTAD/ICC 복합운송증권통일규칙(1991/1992)도 변형단일책임체계.","src":"기출 2023-8 | 기출 2024-20 | 기출 2025-14"},{"t":"과실책임(liability for negligence): 복합운송인이 선량한 관리자로서 적절한 주의의무를 다하지 못한 손해에 대해 책임.","src":"기출 2023-8"},{"t":"무과실책임(strict liability): 과실 여부와 관계없이 책임지되 불가항력 등 면책사유는 인정한다. 면책사유까지 불문하는 절대책임이 아니다.","src":"기출 2023-8 | 보충"},{"t":"UNCTAD/ICC 규칙 책임한도: 1포장당 666.67 SDR 또는 1kg당 2 SDR 중 높은 금액. 해상구간이 없으면 1kg당 8.33 SDR. (UN조약 1980 한도는 이와 다르다)","src":"기출 2025-14 | 보충"},{"t":"UNCTAD/ICC 복합운송증권통일규칙(1991)은 유통성만이 아니라 유통성·비유통성 중 선택.","src":"기출 2022-29"},{"t":"UN 국제복합운송조약(1980): 복합운송인의 책임기간은 화물을 인수한 때부터 인도할 때까지. 적용화물(Goods)에는 송하인이 공급한 컨테이너·파렛트·유사 운송용구와 포장용구를 포함. 송하인은 위험물에 위험성 표식(mark)·꼬리표(label)를 붙여야 한다. 법적 절차 또는 중재 절차가 2년 내에 제기되지 않으면 소송이 무효.","src":"기출 2024-20"}]},{"머리":"FIATA FBL(복합운송증권) 약관","줄":[{"t":"Freight Forwarder: FBL을 발행하고 표면에 기재되어 복합운송계약 이행에 운송인으로서 책임을 지는 복합운송인. Merchant: Shipper, Consignor, Holder, Receiver, Owner of the Goods를 포함.","src":"기출 2022-17"},{"t":"Consignee: Freight Forwarder로부터 화물을 인수할 권리가 있는 자.","src":"기출 2026-20"},{"t":"Method and Route of Transportation 약관: 포워더는 화주에게 고지하지 않고 갑판적·선창적 가능, 화물의 취급·적부·보관·운송의 수단·경로·절차를 자유로이 선택·대체할 재량(liberty).","src":"기출 2024-29"},{"t":"증권 표면 기재사항의 정확성은 Merchant(화주)가 책임진다(포워더 아님).","src":"기출 2024-18"},{"t":"약관은 불법행위를 포함한 모든 손해배상청구에 적용되며, 포워더의 이행보조자 등을 상대로 제기된 경우에도 적용된다.","src":"기출 2024-18"},{"t":"인도일 경과 후 연속일수 90일 이내에 인도되지 않으면 청구자는 멸실된 것으로 간주할 수 있는 것이 통례이다(출제 60일은 오답).","src":"보충 | 기출 2024-18"},{"t":"제소기한: 수화인이 멸실 간주 권리를 가진 날부터 9개월 이내에 소송을 제기하지 않으면 포워더는 모든 책임에서 면제(출제 3개월은 오답).","src":"보충 | 기출 2024-18"}]},{"머리":"복합운송 경로","줄":[{"t":"SLB(Siberia Land Bridge): 극동 해상운송 후 시베리아 횡단철도로 유럽·중동까지.","src":"기출 2022-25"},{"t":"CLB(China Land Bridge): 극동 해상운송 후 중국대륙철도와 실크로드로 유럽까지.","src":"기출 2022-25"},{"t":"Canada Land Bridge: 극동 → 캐나다 서안 해상 → 캐나다 횡단철도(IPI와 다름).","src":"기출 2022-25 | 기출 2023-9 | 보충"},{"t":"ALB(America Land Bridge): 극동 → 미국 서안 해상 → 미국 대륙 철도 횡단 → 동안에서 다시 유럽까지 해상.","src":"기출 2022-25 | 기출 2021-13"},{"t":"MLB(Mini Land Bridge): 극동 → 미국 서안 해상 → 철도(와 트럭)로 미국 동안 또는 멕시코만(걸프) 항만까지.","src":"기출 2021-13 | 기출 2022-25"},{"t":"Micro Land Bridge = IPI(Interior Point Intermodal): 극동 → 북미 서안 해상 → 북미 횡단철도로 미국 내륙 철도터미널·내륙컨테이너터미널에서 인도.","src":"기출 2026-21 | 기출 2022-25"},{"t":"OCP(Overland Common Point): 극동 → 북미 서해안 해상 → 로키산맥 동부 공통운임 지역까지만 철도.","src":"기출 2025-15"},{"t":"RIPI(Reverse Interior Point Intermodal): 극동 → 파나마 운하 경유 → 북미 동안 또는 US 걸프만 항구까지 해상 후 내륙까지 철도·트럭.","src":"기출 2023-9"}]},{"머리":"복합운송의 이점(화주 입장)","줄":[{"t":"전 구간 해상운송보다 수송기간이 짧고, 전 구간 항공운송보다 운임이 저렴(Sea&Air).","src":"기출 2024-22"},{"t":"수송기간 단축으로 재고비용·자본비용 절감, 생산일정·수입상 창고·시장 상황에 맞춘 JIT 납품 가능.","src":"기출 2024-22"}]}],"함정":[{"x":"복합운송주선인 스스로는 운송계약의 주체가 될 수 없으며, 송화인의 주선인으로서 활동한다.","o":"복합운송주선인은 스스로 운송계약의 주체(복합운송인)가 될 수 있다.","src":"기출 2021-17"},{"x":"국제복합운송이라는 용어는 대표적인 국제복합운송 관련 조약인 바르샤바조약 (1929)에서 처음 사용되었다.","o":"'국제복합운송' 용어는 1980년 UN 국제복합운송조약에서 처음 사용되었다. 바르샤바조약(1929)은 항공운송 조약이다.","src":"기출 2021-24 | 보충"},{"x":"국제복합운송의 요건으로 하나의 운송계약, 하나의 책임주체, 단일의 운임, 단일의 운송수단 등을 들 수 있다.","o":"복합운송의 요건은 하나의 운송계약, 하나의 책임주체, 단일 운임, 서로 다른 둘 이상의 운송수단이다. 단일 운송수단이 아니다.","src":"기출 2021-24"},{"x":"국제복합운송이란 국가 간 두 가지 이상의 동일한 운송수단을 이용하여 운송하 는 것이다.","o":"국제복합운송은 국가 간 서로 다른 두 가지 이상의 운송수단을 이용하는 것이다.","src":"기출 2021-24"},{"x":"복합운송 시에는 운송 중 물품 매각이 불필요하기 때문에 복합운송증권은 비유 통성 기명식으로 발행되는 것이 일반적이다.","o":"복합운송증권은 유통성·비유통성 중 선택하여 발행할 수 있다. 비유통성 기명식으로만 발행하는 것이 아니다.","src":"기출 2021-24"},{"x":"복합운송증권은 운송주선인이 발행할 수 없다.","o":"복합운송증권은 복합운송인 역할을 하는 운송주선인(포워더)도 발행할 수 있다(FIATA FBL).","src":"기출 2021-28"},{"x":"복합운송증권상의 복합운송인의 책임구간은 화물 선적부터 최종 목적지에서 양륙 할 때까지이다.","o":"복합운송인의 책임구간은 화물을 인수한 때부터 인도할 때까지이다.","src":"기출 2021-28"},{"x":"복합운송증권상의 복합운송인은 화주에 대해서 구간별 분할책임을 진다.","o":"복합운송인은 전 구간에 대해 단일 책임을 진다(구간별 분할책임이 아님).","src":"기출 2021-28"},{"x":"복합운송증권은 양도가능 형식으로만 발행된다.","o":"복합운송증권은 양도 가능(유통성)·양도 불가능(비유통성) 형식 모두 발행할 수 있다.","src":"기출 2021-28"},{"x":"NVOCC는 자신이 직접 선박을 소유하고 화주와 운송계약을 체결하며 일관선하 증권(through B/L)을 발행한다.","o":"NVOCC는 선박을 소유하지 않고 화주와 운송계약을 체결하며 자기 명의로 B/L(House B/L)을 발행하는 운송인이다.","src":"기출 2022-18"},{"x":"IPI(Interior Point Intermodal)는 한국, 일본 등 극동지역의 화물을 해상운송한 후 캐나다 대륙횡단철도를 이용하여 캐나다의 동해안 항만까지 운송하는 방식이다.","o":"IPI(Interior Point Intermodal)는 극동 → 북미 서안 해상운송 후 철도로 미국 내륙 지점까지 운송하는 방식이다. 캐나다 횡단철도 이용은 Canada Land Bridge이다.","src":"기출 2022-25"},{"x":"UNCTAD/ICC규칙(1991)상 복합운송증권은 유통성으로만 발행하여야 한다.","o":"UNCTAD/ICC규칙(1991)상 복합운송증권은 유통성·비유통성 중 선택하여 발행할 수 있다.","src":"기출 2022-29"},{"x":"무과실책임(liability without negligence)은 복합운송인의 과실여부와 면책사유를 불문하고 운송기간에 발생한 모든 손해의 결과를 책임지는 원칙이다.","o":"무과실책임은 과실 여부와 관계없이 책임지되 불가항력 등 면책사유는 인정한다.","src":"기출 2023-8"},{"x":"UN국제복합운송조약은 복합운송증권의 발행 여부를 송화인의 선택에 따르도록 하고 있다.","o":"UN 국제복합운송조약은 복합운송인이 증권을 발행하게 하고, 유통성·비유통성 형식을 송하인이 선택하도록 한다.","src":"기출 2023-10"},{"x":"운송주선인의 책임: 인도일 경과 후 연속일수 60일 이내에 인도되지 않을 경우 손해배상 청구자는 물품이 멸실된 것으로 간주한다.","o":"연속 90일 이내에 인도되지 않으면 멸실로 간주할 수 있는 것이 통례이다(출제 60일은 오답).","src":"기출 2024-18 | 보충"},{"x":"물품의 명세: 증권표면에 기재된 모든 사항에 대한 정확성은 운송주선인이 책임을 진다.","o":"증권 표면에 기재된 사항의 정확성은 화주(Merchant)가 책임진다.","src":"기출 2024-18"},{"x":"운송주선인의 책임: 운송주선인의 이행보조자를 상대로 제기된 경우에는 이 약 관이 적용되지 않는다.","o":"약관은 운송주선인의 이행보조자를 상대로 제기된 청구에도 적용된다.","src":"기출 2024-18"},{"x":"제소기한: 수하인은 물품이 멸실된 것으로 간주할 수 있는 권리를 가지게 된 날 로부터 3개월 이내에 소송을 제기하지 아니하고 다른 방법에 의해 명확히 합의 되지 않는 한 운송주선인은 모든 책임으로부터 면제된다.","o":"멸실 간주 권리가 생긴 날부터 9개월 이내에 소송을 제기해야 한다(출제 3개월은 오답).","src":"기출 2024-18 | 보충"},{"x":"적용화물(Goods)이란 송하인에 의해 공급된 경우에는 컨테이너, 파렛트 또는 유 사한 운송용구와 포장용구를 포함하지 않는다.","o":"적용화물(Goods)에는 송하인이 공급한 컨테이너·파렛트 또는 유사한 운송용구와 포장용구가 포함된다.","src":"기출 2024-20"},{"x":"항공사가 운송장(Through B/L)을 발행하게 되면 항공사는 함부르크조약으로 책임을 지기 때문에 화주에게 유리하다.","o":"항공사가 Through 운송장을 발행하면 항공구간은 몬트리올(바르샤바) 체제로 책임을 진다. 함부르크 규칙은 해상조약이다.","src":"기출 2024-22"},{"x":"NVOCC는 자체 Tariff를 가질 수 있으나 자기 명의로 B/L을 발행할 수 없다.","o":"NVOCC는 자기 명의로 B/L(House B/L)을 발행할 수 있다.","src":"기출 2025-11"},{"x":"문언증권: 증권에 기재가 없는 사항에 대해서 책임을 부담한다.","o":"문언증권은 증권에 기재된 문언에 따라서만 효력·책임이 정해진다. 기재 없는 사항에는 책임을 부담하지 않는다.","src":"기출 2025-12"},{"x":"복합운송인은 FCL화물을 집화·분류·혼재한 후 Master B/L을 발행한다.","o":"혼재는 LCL화물 대상이다. 포워더형 복합운송인은 House B/L을 발행하고, Master B/L은 선사가 포워더에게 발행한다.","src":"기출 2025-13"},{"x":"FIATA B/L이 널리 사용되고 있고 대부분 비유통성으로 발행된다.","o":"FIATA FBL은 널리 사용되며 유통성(negotiable) 양식이 대부분이다.","src":"기출 2025-30"}]},"#15":{"묶음":[{"머리":"보험 용어","줄":[{"t":"보험료(Insurance Premium): 보험자의 위험부담에 대해 보험계약자가 지급하는 보수(대가). 보험금액이 아니다.","src":"기출 2025-38 | 기출 2023-35"},{"t":"피보험자(Insured): 피보험이익의 주체로서 보험사고로 손해를 입은 경우 보상받을 권리를 갖는 자.","src":"기출 2025-38"},{"t":"피보험이익(Insurable Interest): 보험의 목적이 멸실·손상되면 경제적 손해를 입게 되는 피보험자와 보험목적 사이의 이해관계.","src":"기출 2025-38 | 기출 2023-35"},{"t":"보험가액(Insurable Value): 피보험이익의 평가액. 피보험이익에 대해 발생할 수 있는 경제적 손해의 최고한도액.","src":"기출 2025-38"},{"t":"보험금액(Insured amount): 실제로 보험에 가입한 금액. 보험자가 보험계약상 부담하는 손해배상책임의 최고한도액.","src":"기출 2025-38 | 기출 2023-35"},{"t":"보험금(Claim Amount): 보험사고 발생 시 보험자가 실제로 지급하는 금액(보험금액과 구별).","src":"기출 2025-38 | 보충"},{"t":"Warranty(담보): 보험계약자(피보험자)가 반드시 지켜야 할 약속.","src":"기출 2023-35"},{"t":"Duty of disclosure(고지의무): 피보험자 등이 보험계약 체결에 영향을 줄 수 있는 모든 중요한 사실을 보험자에게 알려야 할 의무.","src":"기출 2023-35"},{"t":"Duration of insurance(보험기간): 보험자의 위험부담책임이 시작되는 때부터 종료될 때까지의 기간.","src":"기출 2023-35"}]},{"머리":"보험증권 종류(MIA 1906)","줄":[{"t":"Floating policy(포괄예정보험증권): 보험을 일반적 용어로 기술하고 선박 명칭 등 상세는 추후 선적통지(declaration)로 확정하도록 남겨 두는 증권. 통지는 증권 배서 또는 관습적 방법으로 한다.","src":"기출 2024-31"},{"t":"Valued policy(기평가보험증권), Unvalued policy(미평가), Open policy(개방), Fixed policy는 선택지에 나온 다른 증권.","src":"기출 2024-31"}]},{"머리":"위부(Abandonment)와 전손","줄":[{"t":"위부: 피보험자가 잔존물에 대한 모든 권리를 보험자에게 이전하고 전손보험금을 청구하는 행위.","src":"기출 2021-37"},{"t":"위부의 통지: 피보험자가 손해를 추정전손으로 처리하겠다는 의사표시.","src":"기출 2021-37"},{"t":"보험자가 위부통지를 수락하면 잔존물에 대한 일체의 권리가 보험자에게 이전된다.","src":"기출 2021-37"},{"t":"피보험자가 위부통지를 하지 않으면 손해는 분손으로 처리된다.","src":"기출 2021-37"},{"t":"보험목적물이 전멸해 회수할 잔존물이 없으면 위부 통지가 필요 없다(현실전손).","src":"기출 2021-37 | 보충"},{"t":"추정전손(Constructive Total Loss, MIA 1906) 해당: 선박의 수선·수리비가 수리 후 목적물 시가보다 클 때, 화물의 수선비와 도착지까지 운반비 합계가 도착 후 화물가액을 초과할 때, 화물을 회복하는 비용이 회복 후 가액을 초과할 때, 점유권 박탈로 회복 가망이 없을 때.","src":"기출 2026-36"},{"t":"침몰되고 있는 선박을 가볍게 하려고 적재 화물을 바다에 버리는 투하(jettison)는 공동해손 희생이며 추정전손이 아니다.","src":"기출 2026-36 | 보충"}]},{"머리":"해상손해의 종류","줄":[{"t":"물적손해: 보험목적물의 완전한 파손·멸실(전손), 일부에 발생한 손해로서 피보험자 단독 손해(단독해손), 공동의 안전을 위해 희생되어 이해관계자들이 공동 분담하는 손해(공동해손 희생), 선박의 수리비가 수리 후 선박가액을 초과하는 경우(추정전손).","src":"기출 2023-37"},{"t":"손해방지비용은 보험목적물에 해상위험이 발생했을 때 손해방지의무를 이행하려고 지출한 비용으로, 물적손해가 아니라 비용손해이다.","src":"기출 2023-37"},{"t":"공동해손(General Average) 정산에 사용하는 국제규칙: York-Antwerp Rules(YAR).","src":"기출 2021-38"}]},{"머리":"특별비용·손해방지비용","줄":[{"t":"특별비용(particular charges): 보험목적물의 안전·보존을 위해 지출된 비용 중 공동해손비용과 손해방지비용을 제외한 것. 구조계약 체결로 발생한 비용 등.","src":"기출 2022-33 | 보충"},{"t":"특별비용은 보험자가 담보하는 위험에 의한 손해와 관련해 정당하게 지출된 경우에 보상된다. 보험조건·담보위험 여부와 무관하게 보상되는 것이 아니다.","src":"기출 2022-33 | 보충"},{"t":"손해방지비용은 피보험자 측(피보험자·대리인·사용인)이 손해방지의무를 이행해 지출한 비용이다. 제3자나 보험자의 손해방지행위 비용은 손해방지비용으로 보상되지 않는다.","src":"기출 2022-33 | 보충"}]}],"함정":[{"x":"보험목적물이 전멸하여 보험자가 회수할 잔존물이 없더라도 위부를 통지하여야 한다.","o":"보험목적물이 전멸하여 회수할 잔존물이 없으면 위부 통지는 필요 없다.","src":"기출 2021-37"},{"x":"특별비용은 공동해손과 손해방지비용을 모두 포함한 비용을 말한다.","o":"특별비용은 공동해손과 손해방지비용을 제외한 보험목적물의 안전·보존을 위한 비용이다.","src":"기출 2022-33"},{"x":"제3자나 보험자가 손해방지행위를 했다면 그 비용은 손해방지비용으로 보상될 수 있다.","o":"손해방지비용은 피보험자 측이 손해방지의무를 이행하여 지출한 비용이다. 제3자나 보험자의 행위 비용은 해당하지 않는다.","src":"기출 2022-33"},{"x":"특별비용은 보험조건에 상관없이 정당하게 지출된 경우 보험자로부터 보상받을 수 있다.","o":"특별비용은 보험자가 담보하는 위험과 관련된 경우에 보상된다.","src":"기출 2022-33"},{"x":"보험자의 담보위험 여부에 상관없이 발생한 손해를 방지하기 위해 지출한 구조 비는 보상받을 수 있다.","o":"보험자의 담보위험에 의한 손해를 방지하기 위한 구조비 등만 보상받을 수 있다.","src":"기출 2022-33"},{"x":"Insured amount란 피보험위험으로 인하여 발생한 손해를 보험자로부터 보상받 는 대가로 보험계약자가 보험자에게 지급하는 수수료를 말한다.","o":"보험금액(Insured amount)은 보험자가 부담하는 최고한도 금액이다. 보험계약자가 지급하는 대가는 보험료이다.","src":"기출 2023-35"},{"x":"보험금(Claim Amount)은 실제로 보험에 가입한 금액을 말하며 보험자가 보험 계약상 부담하는 손해배상책임의 최고한도액을 말한다.","o":"보험금액(Insured amount)은 실제 가입한 금액이자 보험자 책임의 최고한도이다. 보험금(Claim amount)은 사고 시 보험자가 지급하는 금액이다.","src":"기출 2025-38"}]},"#16":{"묶음":[{"머리":"ICC(A) 2009","줄":[{"t":"ICC(A): 포괄담보(all risks) 방식. 면책위험으로 열거된 것 외의 위험을 담보한다.","src":"보충"},{"t":"ICC(A) 면책위험 예: 보험목적물의 고유의 하자·성질로 인한 손상, 포획·나포·강류·억지·억류(해적행위 제외)와 그 결과 손상, 피보험자가 적재 시 알고 있는 선박·부선의 불감항으로 생긴 손상, 동맹파업자·직장폐쇄 노동자·노동쟁의·소요·폭동 가담자에 의한 손상.","src":"기출 2022-31"},{"t":"어떠한 자의 불법행위에 의한 고의적 손상 또는 고의적 파괴(malicious damage)는 ICC(A) 면책위험이 아니다(담보한다). ICC(B)·(C)에서는 면책.","src":"기출 2022-31 | 보충"}]},{"머리":"ICC(C) 2009 담보위험","줄":[{"t":"ICC(C) 담보: 화재·폭발, 본선·부선의 좌초·교사·침몰·전복, 육상운송용구의 전복·탈선, 피난항에서 화물의 양하(양륙), 공동해손희생, 투하 등.","src":"기출 2024-37 | 기출 2025-33"},{"t":"ICC(C)가 담보하지 않는 위험: 지진·화산 분화·낙뢰 등 자연재해 (ICC(B)에는 있음). 포장이나 준비의 불충분·부적합으로 인한 손해는 면책위험.","src":"기출 2025-33 | 기출 2024-37 | 보충"}]},{"머리":"ICC(B)·(C) 부가위험(추가 부보)","줄":[{"t":"ICC(B)·(C)에 할증보험료로 추가 부보 가능한 부가위험: 기름 등 선내 청소 불충분으로 인한 오손·타화물 접촉 손해(오손), 하역 중 갈고리 사용 손해(Hook damage), 선창 내 열 상승과 갑작스런 냉각에 의한 수증기 응결 위험(Sweat and heat), 도난·발하·타항 양하 또는 분실로 인한 포장 전체의 불착(TPND).","src":"기출 2026-37"},{"t":"선박·부선의 좌초·교사·침몰·전복은 ICC(B)·(C)의 기본 담보위험이므로 부가위험이 아니다.","src":"기출 2026-37"}]}],"함정":[]},"#17":{"묶음":[{"머리":"미국 중심 보안제도","줄":[{"t":"CSI(Container Security Initiative): 미국 세관직원이 수출국 항구에 파견되어 수출국 세관직원과 합동으로 미국행 컨테이너 중 위험요소가 큰 화물을 선별해 선적 전에 검사하는 컨테이너 보안 협정.","src":"기출 2022-26 | 기출 2025-28"},{"t":"C-TPAT(Customs-Trade Partnership Against Terrorism): 미국 세관이 테러방지 목적으로 만든 업체 협력 프로그램. 해외 판매자로부터 미국 국경에 이르기 전 공급망 보안을 강화. 인증업체에는 세관검사 축소 등 통관상 혜택.","src":"기출 2026-24 | 기출 2025-28"},{"t":"24-Hour Rule: 해상운송인과 NVOCC가 미국행 컨테이너가 선적되기 24시간 전에 화물 세부정보를 미국 관세청에 제출. CSI의 후속조치. 적하목록을 적재 24시간 전에 신고.","src":"기출 2023-30 | 기출 2025-28"},{"t":"Trade Act of 2002 Final Rule: 해상뿐 아니라 항공·철도·트럭 등 모든 운송수단으로 미국에 수입되는 화물정보를 미국 관세청에 사전 제출.","src":"기출 2024-30 | 기출 2023-30"},{"t":"10+2 Rule(수입자 보안신고, ISF)은 선택지에 나온 다른 미국 보안제도.","src":"기출 2022-26 | 기출 2023-30"}]},{"머리":"국제 보안제도","줄":[{"t":"ISPS Code(국제선박항만시설보안규칙): 선박과 항만시설의 보안위협을 탐지·제거하기 위한 규정.","src":"기출 2021-27 | 기출 2024-6"},{"t":"AEO(Authorized Economic Operator, 공인경제운영인): 세계관세기구(WCO)의 수출입 공급망 안전관리 기준 또는 이와 동등한 기준을 준수하여 자국 세관의 인증을 받은 국제수출입공급망의 개별 당사자. WTO가 고안한 제도가 아니다.","src":"기출 2024-39 | 기출 2025-28"},{"t":"ISO 28000: 공급사슬 전반의 보안을 보장하기 위해 제조업자뿐 아니라 창고보관업자·운송업자·서비스업자 등 공급사슬 참여 모든 조직의 보안 사항을 심사·인증하는 물류보안 인증제도.","src":"기출 2021-27 | 기출 2025-28"},{"t":"ISO 28000 심사 내용 6가지: 일반사항, 보안경영방침, 보안위험평가 및 기획·실행·운영, 점검 및 시정조치, 경영검토, 지속적인 개선.","src":"기출 2021-27 | 기출 2025-28"}]}],"함정":[{"x":"AEO는 WTO에서 무역안전과 원활화에 관한 국제규범의 일환으로 고안한 제도이다.","o":"AEO는 세계관세기구(WCO)의 수출입 공급망 안전관리 기준에서 도입한 제도이다.","src":"기출 2025-28"}]},"#18":{"묶음":[{"머리":"관세법 정의","줄":[{"t":"수입: 외국물품을 우리나라에 반입(보세구역을 경유하는 것은 보세구역으로부터 반입)하거나 우리나라에서 소비 또는 사용하는 것(운송수단 안의 소비·사용 포함, 제239조 각 호는 제외).","src":"관세법 제2조제1호"},{"t":"수출: 내국물품을 외국으로 반출하는 것. 반송: 국내에 도착한 외국물품이 수입통관절차를 거치지 않고 다시 외국으로 반출되는 것.","src":"관세법 제2조제2호·제3호"},{"t":"외국물품: ①외국으로부터 우리나라에 도착한 물품(외국 선박 등이 공해에서 채집·포획한 수산물 등 포함)으로서 수입신고가 수리되기 전의 것 ②수출신고가 수리된 물품.","src":"관세법 제2조제4호"},{"t":"내국물품: ①우리나라에 있는 물품으로서 외국물품이 아닌 것 ②우리나라 선박 등이 공해에서 채집·포획한 수산물 등 ③입항전수입신고가 수리된 물품 ④수입신고수리전 반출승인을 받아 반출된 물품 ⑤수입신고전 즉시반출신고를 하고 반출된 물품.","src":"관세법 제2조제5호"},{"t":"수입신고가 수리되기 전의 외국 도착 물품은 외국물품이다(내국물품 아님). 보세공장에서 내국물품과 외국물품을 원재료로 만든 물품은 내국물품 목록에 해당하지 않는다(기출 정답).","src":"기출 2023-36 | 기출 2024-40 | 관세법 제2조제5호"},{"t":"통관: 이 법에 따른 절차를 이행하여 물품을 수출·수입 또는 반송하는 것.","src":"관세법 제2조제13호"},{"t":"환적: 동일한 세관 관할구역에서 입국·입항하는 운송수단에서 출국·출항하는 운송수단으로 물품을 옮겨 싣는 것. 복합환적: 입국·입항 운송수단의 물품을 다른 세관 관할구역으로 운송하여 출국·출항 운송수단으로 옮겨 싣는 것.","src":"관세법 제2조제14호·제15호"},{"t":"탁송품: 상업서류·견본품·자가사용물품 등 국제무역선·국제무역기 또는 국경출입차량을 이용한 물품 송달을 업으로 하는 자에게 위탁하여 반입·반출하는 물품.","src":"관세법 제2조제18호"}]},{"머리":"수입으로 보지 아니하는 소비·사용","줄":[{"t":"①선박용품·항공기용품·차량용품을 운송수단 안에서 그 용도에 따라 소비·사용 ②이 용품을 세관장이 정하는 지정보세구역에서 출입국관리법에 따라 출국심사를 마치거나 입국하지 않고 경유하여 제3국으로 출발하려는 자에게 제공하여 소비·사용 ③여행자가 휴대품을 운송수단 또는 관세통로에서 소비·사용 ④이 법에서 인정하는 바에 따라 소비·사용.","src":"관세법 제239조"},{"t":"관세법에 의해 매각된 물품을 용도에 따라 소비·사용하는 경우는 제239조에 열거되지 않았다.","src":"기출 2025-32 | 관세법 제239조"}]},{"머리":"수출입신고","줄":[{"t":"물품을 수출·수입 또는 반송하려면 품명·규격·수량·가격과 그 밖에 대통령령으로 정하는 사항을 세관장에게 신고해야 한다.","src":"관세법 제241조제1항"},{"t":"신고 생략 또는 간소 신고 가능 물품: ①휴대품·탁송품·별송품 ②우편물 ③관세 면제 물품(제91~94조, 제96조제1항, 제97조제1항) ④일부 운송수단 ⑤국제운송용 컨테이너(관세율 무세 한정).","src":"관세법 제241조제2항"},{"t":"해외로 수출·반송하는 운송수단은 신고 생략 대상에서 제외된다(최초 수입 반입 운송수단, 해외 수리·부품교체 운송수단과 함께).","src":"관세법 제241조제2항제3호의2 단서 | 기출 2021-34"},{"t":"수입하거나 반송할 물품을 지정장치장·보세창고에 반입하거나 보세구역이 아닌 장소에 장치한 자는 그 반입일 또는 장치일부터 30일 이내에 신고해야 한다. 기간 내 미신고 시 과세가격의 100분의 2 범위에서 가산세.","src":"관세법 제241조제3항·제4항"},{"t":"신고 명의: 화주 또는 관세사등. 다만 수출신고는 화주에게 수출물품을 제조·공급한 자의 명의로도 할 수 있다. 수입신고·반송신고는 완제품공급자 명의로 할 수 없다.","src":"관세법 제242조 | 기출 2023-39"},{"t":"수입신고는 물품을 적재한 선박·항공기가 입항한 후에만 할 수 있는 것이 원칙(제243조제2항). 신속한 통관이 필요하면 입항 전에 수입신고 가능(입항전수입신고), 이 경우 입항전수입신고된 물품은 우리나라에 도착한 것으로 본다.","src":"관세법 제243조제2항 | 관세법 제244조제1항 | 기출 2022-38 | 기출 2023-39"},{"t":"항공기로 수입되는 물품, 일본·중국·대만·홍콩에서 선박으로 수입되는 물품은 출항 전 수입신고가 가능하다.","src":"기출 2026-33 | 보충(원문 미확인)"},{"t":"반송신고는 물품이 이 법에 따른 장치 장소에 있는 경우에만 할 수 있다.","src":"관세법 제243조제3항"},{"t":"신고 시 과세가격결정자료 외에 대통령령이 정하는 서류를 제출한다. 관세사등에게 제출·확인시킨 경우 제출 생략·수입신고 수리 후 제출 가능.","src":"관세법 제245조"},{"t":"세관공무원은 수출·수입·반송 물품을 검사할 수 있고, 관세청장은 검사대상·범위·방법 등 필요한 기준을 정할 수 있다. 화주는 수입신고 전에 확인할 수 있다.","src":"관세법 제246조"},{"t":"세관장은 신고가 적합하면 지체 없이 수리하고 신고필증을 발급한다. 수리 전에는 신고된 물품을 운송수단·관세통로·하역통로·장치장소에서 반출해서는 안 된다. 신고서 기재사항이 갖추어지지 않으면 보완하게 할 수 있다.","src":"관세법 제248조 | 기출 2022-38 | 기출 2023-39"},{"t":"수입신고수리전 반출: 관세에 상당하는 담보를 제공하고 세관장의 승인을 받아야 한다. 즉시반출: 수입신고 전 즉시반출신고를 하고 반출하며, 신고한 날부터 10일 이내에 수입신고. 위반 시 관세 부과·징수와 가산세(관세의 20%).","src":"관세법 제252조 | 관세법 제253조"}]},{"머리":"보세운송","줄":[{"t":"외국물품은 국제항, 보세구역, 제156조에 따라 허가된 장소, 세관관서, 통관역, 통관장, 통관우체국 간에 한정하여 외국물품 그대로 운송할 수 있다.","src":"관세법 제213조제1항"},{"t":"보세운송하려는 자는 관세청장이 정하는 바에 따라 세관장에게 보세운송 신고를 해야 한다. 다만 물품의 감시 등을 위해 필요하다고 인정하여 대통령령으로 정하는 경우에는 세관장의 승인을 받아야 한다.","src":"관세법 제213조제2항"},{"t":"세관공무원은 감시·단속을 위해 필요하면 관세청장이 정하는 바에 따라 보세운송 물품을 검사할 수 있다.","src":"관세법 제213조제3항"},{"t":"수출신고가 수리된 물품은 관세청장이 따로 정하는 것을 제외하고 보세운송절차를 생략한다.","src":"관세법 제213조제4항"},{"t":"보세운송 신고·승인신청은 화주, 관세사등, 보세운송업자의 명의로 해야 한다.","src":"관세법 제214조"},{"t":"보세운송 신고·승인을 받은 자는 물품이 운송 목적지에 도착하면 도착지 세관장에게 보고해야 한다(출발지 세관장 아님).","src":"관세법 제215조"},{"t":"세관장은 감시·단속상 필요하면 운송통로를 제한할 수 있고, 보세운송은 관세청장이 정하는 기간 내에 끝내야 한다(재해 등 부득이한 사유로 세관장이 연장 가능). 신고·승인받은 운송수단을 이용해야 한다.","src":"관세법 제216조"},{"t":"관세청장이 승인 대상으로 하지 않아도 화물관리와 불법 수출입 방지에 지장이 없다고 정한 물품은 신고만으로 보세운송할 수 있다.","src":"기출 2026-34"}]},{"머리":"보세구역","줄":[{"t":"보세창고: 외국물품이나 통관하려는 물품을 장치. 운영인은 세관장에게 미리 신고하면 장치에 방해되지 않는 범위에서 내국물품도 장치할 수 있다. 1년(수입신고 수리 물품 계속 장치는 6개월) 이상 내국물품만 장치하려면 세관장 승인.","src":"관세법 제183조"},{"t":"보세창고 장치기간은 외국물품·내국물품 모두 1년의 범위에서 관세청장이 정하고, 세관장이 필요하다고 인정하면 1년의 범위에서 연장할 수 있다.","src":"관세법 제177조제1항"},{"t":"보세공장: 외국물품을 원료·재료로 하거나, 외국물품과 내국물품을 원료·재료로 하여 제조·가공할 수 있다. 내국물품만 원료로 하는 작업은 세관장의 허가를 받아야 한다.","src":"관세법 제185조"},{"t":"보세전시장: 박람회·전람회·견본품 전시회 등의 운영을 위해 외국물품을 장치·전시하거나 사용할 수 있다.","src":"관세법 제190조"},{"t":"보세건설장: 외국물품을 반입하면 사용 전에 수입신고를 하고 세관공무원의 검사를 받아야 한다(검사 불필요 시 생략 가능).","src":"관세법 제192조"},{"t":"보세판매장: 외국 반출 조건 등으로 판매. 판매 물품의 반입·반출·인도·관리에 필요한 사항은 대통령령으로 정한다(산업통상자원부령 아님).","src":"관세법 제196조제3항"},{"t":"국제항은 대통령령으로 지정한다. 항구: 인천항, 부산항, 마산항, 여수항, 목포항, 군산항, 제주항, 동해·묵호항, 울산항, 통영항, 삼천포항, 장승포항, 포항항, 장항항, 옥포항, 광양항, 평택·당진항, 대산항, 삼척항, 진해항, 완도항, 속초항, 고현항, 경인항, 보령항. 강릉항은 목록에 없다.","src":"관세법 제133조 | 관세법 시행령 제155조 | 기출 2026-22"},{"t":"국제공항: 인천공항, 김포공항, 김해공항, 제주공항, 청주공항, 대구공항, 무안공항, 양양공항.","src":"관세법 시행령 제155조제1항"}]},{"머리":"무역구제관세","줄":[{"t":"덤핑방지관세: 외국물품이 정상가격 이하로 덤핑수입되어 국내산업이 실질적 피해를 받거나 받을 우려가 있고(또는 산업발전이 실질적으로 지연), 조사로 확인되면 정상가격과 덤핑가격의 차액 이하의 관세를 추가 부과.","src":"관세법 제51조 | 기출 2024-35"},{"t":"상계관세: 외국에서 보조금·장려금을 받은 물품의 수입으로 국내산업이 실질적 피해를 받거나 받을 우려가 있으면 조사 후 보조금 등의 금액 이하의 관세를 추가 부과.","src":"관세법 제57조 | 기출 2024-35"},{"t":"긴급관세(세이프가드): 특정물품의 수입 증가로 국내산업이 심각한 피해를 받거나 받을 우려가 있으면 필요한 범위에서 관세를 추가 부과(공정한 수출행위에 의한 수입도 대상). 긴급관세는 부과이지 인하가 아니다.","src":"관세법 제65조제1항 | 기출 2024-35"},{"t":"긴급관세 부과 시 이해당사국과 부정적 효과에 대한 적절한 무역보상방법에 관해 협의할 수 있다.","src":"관세법 제65조제3항 | 기출 2024-35"},{"t":"긴급관세 부과기간은 4년을 초과할 수 없고 잠정긴급관세는 200일을 초과할 수 없다. 재심사로 연장해도 총 적용기간은 8년을 초과할 수 없다.","src":"관세법 제65조제5항"}]},{"머리":"보세구역 종류와 외국물품 장치","줄":[{"t":"보세구역은 지정보세구역·특허보세구역·종합보세구역으로 구분한다. 지정보세구역은 지정장치장·세관검사장, 특허보세구역은 보세창고·보세공장·보세전시장·보세건설장·보세판매장.","src":"관세법 제154조"},{"t":"외국물품은 보세구역이 아닌 장소에 장치할 수 없다. 예외: 수출신고 수리 물품, 크기·무게가 과다하여 보세구역 장치가 곤란한 물품, 재해 등으로 임시 장치한 물품, 검역물품, 압수물품, 우편물품.","src":"관세법 제155조제1항"},{"t":"보세구역이 아닌 장소에 장치가 곤란한 외국물품을 두려는 자는 세관장의 허가를 받아야 하고, 세관장은 담보 제공·시설 설치를 명할 수 있다.","src":"관세법 제156조"}]}],"함정":[{"x":"보세운송을 하려는 자는 물품의 감시 등을 위하여 필요하다고 인정하여 대통령 령으로 정하는 경우 세관장에게 보세운송신고를 하여야 한다.","o":"보세운송은 원칙적으로 세관장에게 신고하고, 물품 감시 등을 위해 필요하다고 인정해 대통령령으로 정하는 경우에는 세관장의 승인을 받아야 한다.","src":"기출 2021-33 | 관세법 제213조제2항"},{"x":"보세창고의 경우 장치기간이 지난 내국물품은 그 기간이 지난 후 30일 내에 반 출하면 된다.","o":"보세창고 내국물품의 장치기간은 1년의 범위에서 관세청장이 정하고 세관장이 필요하면 1년의 범위에서 연장할 수 있다. '기간이 지난 후 30일 내 반출'은 현행 법문에 없다(출제 오답).","src":"기출 2022-36 | 관세법 제177조"},{"x":"보세공장에서는 내국물품은 사용할 수 없고, 외국물품만을 원료 또는 재료로 하 여 제품을 제조ㆍ가공할 수 있다.","o":"보세공장에서는 외국물품만이 아니라 외국물품과 내국물품을 원료·재료로 하여 제조·가공할 수 있다.","src":"기출 2022-36 | 관세법 제185조"},{"x":"보세건설장 운영인은 보세건설장에서 건설된 시설을 수입신고가 수리되기 전에 가동해도 된다.","o":"보세건설장에 반입한 외국물품은 사용 전에 수입신고를 하고 검사를 받아야 한다.","src":"기출 2022-36 | 관세법 제192조"},{"x":"보세판매장에서 판매하는 물품의 반입, 반출, 인도, 관리에 관한 사항은 산업통상 자원부령으로 정한다.","o":"보세판매장 판매 물품의 반입·반출·인도·관리에 필요한 사항은 대통령령으로 정한다.","src":"기출 2022-36 | 관세법 제196조제3항"},{"x":"여행자가 외국물품인 휴대품을 관세통로에서 소비하거나 사용하는 경우는 수입 으로 본다.","o":"여행자가 휴대품을 운송수단 또는 관세통로에서 소비·사용하는 경우는 수입으로 보지 않는다.","src":"기출 2022-38 | 관세법 제239조"},{"x":"수입신고와 반송신고는 물품의 화주 또는 완제품공급자나 이들을 대리한 관세사 등의 명의로 해야 한다.","o":"수입신고·반송신고는 화주 또는 관세사등의 명의로 한다. 제조·공급자 명의는 수출신고에만 허용된다.","src":"기출 2023-39 | 관세법 제242조"},{"x":"긴급관세(세이프가드)제도는 수출국의 공정한 수출행위에 의한 수입이지만 특정 물품의 수입이 급격히 증가하여 국내산업에 심각한 피해를 받거나 받을 우려가 있을 때 조사를 실시하여 긴급관세를 인하한다.","o":"긴급관세(세이프가드)는 조사 후 관세를 추가로 부과한다(인하가 아님).","src":"기출 2024-35 | 관세법 제65조제1항"},{"x":"보세운송 중에는 세관의 감시ㆍ단속을 일시 벗어나게 되므로 운송통로와 운송 기간을 제한하지 않고 있다.","o":"세관장은 보세운송 감시·단속상 필요하면 운송통로를 제한할 수 있고, 보세운송은 관세청장이 정하는 기간 내에 끝내야 한다.","src":"기출 2025-36 | 관세법 제216조"},{"x":"보세운송의 신고를 하거나 승인을 받은 자는 해당 물품이 운송 출발지에 도착 하였을 때에는 관세청장이 정하는 바에 따라 출발지의 세관장에게 보고하여야 한다.","o":"보세운송 신고·승인을 받은 자는 물품이 운송 목적지에 도착하면 도착지 세관장에게 보고한다.","src":"기출 2026-34 | 관세법 제215조"}]},"#19":{"묶음":[{"머리":"클레임 해결 방법","줄":[{"t":"당사자 간 해결: 청구권 포기, 타협(Amicable settlement) 등. 제3자 개입 없음.","src":"기출 2026-35 | 보충"},{"t":"제3자 개입 해결: 알선(Intermediation), 조정(Conciliation), 중재(Arbitration), 소송(Litigation). Amicable settlement는 제3자 개입 방법이 아니다.","src":"기출 2026-35"}]},{"머리":"중재제도의 특징","줄":[{"t":"중재인은 해당 분야 전문가인 민간인이며 당사자 합의로 선정한다. 법원이 임명하는 것이 아니다.","src":"기출 2022-34 | 중재법 제12조"},{"t":"중재는 비공개로 진행되어 사업상 비밀을 유지할 수 있다.","src":"기출 2022-34"},{"t":"중재합의는 분쟁 발생 전후를 기준으로 사전합의(중재조항)와 사후합의(중재계약) 방식이 있다.","src":"기출 2022-34"},{"t":"뉴욕협약(1958)에 가입된 국가 간에는 중재판정의 승인 및 집행이 보장된다.","src":"기출 2022-34"},{"t":"중재판정은 양쪽 당사자 간에 법원의 확정판결과 동일한 효력을 가진다(승인·집행 거절 사유가 있으면 예외). 중재인은 자신이 내린 판정을 철회·변경할 수 없다.","src":"중재법 제35조 | 기출 2022-34"}]},{"머리":"중재법(현행) 조문","줄":[{"t":"중재합의는 서면으로 하며, 독립된 합의 또는 계약에 중재조항을 포함하는 형식으로 할 수 있다.","src":"중재법 제8조제1항·제2항"},{"t":"중재합의 당사자는 중재절차의 개시 전 또는 진행 중에 법원에 보전처분을 신청할 수 있다.","src":"중재법 제10조"},{"t":"중재인의 수는 당사자 합의로 정하고, 합의가 없으면 3명으로 한다.","src":"중재법 제11조"},{"t":"당사자 간 다른 합의가 없으면 중재인은 국적에 관계없이 선정될 수 있다. 선정절차는 합의로 정한다.","src":"중재법 제12조제1항·제2항"},{"t":"합의가 없을 때 단독중재인: 중재인 선정을 요구받은 후 30일 이내에 합의하지 못하면 어느 한쪽의 신청으로 법원 또는 법원이 지정한 중재기관이 선정. 3명: 각 당사자가 1명씩 선정하고 선정된 2명이 합의해 나머지 1명을 선정.","src":"중재법 제12조제3항"},{"t":"중재인은 공정성·독립성에 의심을 살 사유가 있으면 지체 없이 당사자들에게 고지해야 하고, 그 사유가 있거나 합의한 자격을 갖추지 못한 경우에만 기피될 수 있다.","src":"중재법 제13조"},{"t":"다른 합의가 없으면 중재절차는 피신청인이 중재요청서를 받은 날부터 시작된다. 중재요청서에는 당사자, 분쟁의 대상, 중재합의의 내용을 적는다.","src":"중재법 제22조"},{"t":"중재절차에서 사용될 언어: 당사자 합의 → 없으면 중재판정부 지정 → 지정이 없으면 한국어.","src":"중재법 제23조"},{"t":"중재절차 진행 중 당사자들이 화해하면 중재판정부는 그 절차를 종료한다. 화해 내용을 중재판정 형식으로 적을 수 있고 본안 중재판정과 같은 효력.","src":"중재법 제31조 | 기출 2021-40"}]},{"머리":"상사중재 절차(기출 순서)","줄":[{"t":"분쟁 당사자가 중재계약에 따라 중재기관에 중재신청 → 중재비용 선납 → 중재기관이 신청인·피신청인에게 각각 등록통지 → 중재기관이 먼저 조정을 거치고 실패 시 중재장소 합의·중재인 선정 → 선정된 중재인이 양 당사자 주장·증거에 입각해 심문하고 판정.","src":"기출 2025-34"}]}],"함정":[{"x":"중재합의의 당사자는 중재절차의 진행 중에는 법원에 보전처분을 신청할 수 없다.","o":"중재합의 당사자는 중재절차의 개시 전 또는 진행 중에 법원에 보전처분을 신청할 수 있다.","src":"기출 2021-40 | 중재법 제10조"},{"x":"중재인은 해당분야 전문가인 민간인으로서 법원이 임명한다.","o":"중재인은 당사자 합의로 선정한다. 합의가 없으면 법원 또는 법원이 지정한 중재기관이 선정한다.","src":"기출 2022-34 | 중재법 제12조"}]}};
